    exam_year,
    status,
    difficulty,
    unit,
    topic
) VALUES (
    'The immediate action in a patient with sickle cell anemia who develops priapism is:-',
    'Caution the patient against passing urine till the priapism resolves',
    'Make the patient to lie still on bed',
    'Have the patient take a warm bath',
    'Administer morphine at the onset of the attack',
    'C',
    'In sickle cell disease, priapism is a vaso-occlusive crisis; conservative first-line measures include hydration, warmth (warm bath), emptying the bladder by voiding, and analgesia. A warm bath promotes vasodilation and venous drainage to relieve the engorgement, making it the appropriate immediate nursing action per Brunner & Suddarth and Kenya haematology management.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Medical-Surgical Nursing',
    'General Medical-Surgical'
) ON CONFLICT (stem, cadre) DO NOTHING;

