) VALUES (
    'The oral-dental condition is a common complaint among the elderly is:-',
    'Halitosis',
    'Bruxism',
    'Dental abscess',
    'Xerostomia',
    'D',
    'Xerostomia (dry mouth) is the most common oral-dental complaint among the elderly, resulting from reduced salivary flow, polypharmacy and age-related changes. It predisposes to caries, infection and difficulty swallowing, per Kozier Fundamentals and gerontological nursing references.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Mental Health Nursing',
    'General Mental'
) ON CONFLICT (stem, cadre) DO NOTHING;

