    unit,
    topic
) VALUES (
    'The most appropriate time to administer an antacid is:-',
    'With the meal.',
    '30 minutes before the meal.',
    'Immediately after the meal.',
    '1 – 3 hours after the meal.',
    'D',
    'Antacids are most effective when acid production and gastric emptying peak; giving them 1-3 hours after meals prolongs their neutralizing action as food buffering wanes. This timing is per pharmacology/therapeutic guidelines for peptic acid disorders.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Pharmacology',
    'General Pharmacology'
) ON CONFLICT (stem, cadre) DO NOTHING;

INSERT INTO questions (
    stem,
    option_a,
    option_b,
    option_c,
    option_d,
    correct_option,
    rationale,
    cadre,
    paper,
    exam_year,
    status,
    difficulty,
    unit,
    topic
) VALUES (
    'A physician has prescribed Novolog insulin for a client with diabetes mellitus. Which statement indicates that the client knows when the peak action of the insulin occurs:-',
    '“I will make sure I eat breakfast within 10 minutes of taking my insulin.”',
    '“I will need to carry candy or some form of sugar with me all the time.”',
    '“I will eat a snack around three o’clock each afternoon.”',
    '“I can save my dessert from supper for a bedtime snack.”',
    'A',
    'Novolog (insulin aspart) is a rapid-acting insulin with onset 10-20 minutes and peak at 1-3 hours; the client must eat within 5-15 minutes to prevent hypoglycaemia at peak action. Eating immediately after dosing demonstrates correct understanding of its rapid onset/peak, per pharmacology guidelines.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Medical-Surgical Nursing',
    'General Medical-Surgical'
) ON CONFLICT (stem, cadre) DO NOTHING;

INSERT INTO questions (
    stem,
    option_a,
