    exam_year,
    status,
    difficulty,
    unit,
    topic
) VALUES (
    'The nurse prepares a liquid medication and then finds that the client no longer needs the medication. The most appropriate action is:-',
    'To keep the count correct, record that the drug was taken',
    'Charge for the dose because it must be paid for',
    'Record the medication as “not taken” and discard the poured dose',
    'Pour the medication back into the container',
    'C',
    'A poured/prepared dose that is no longer needed must be discarded (a poured medication is never returned to the stock container due to contamination risk) and documented as not given. This adheres to medication administration safety standards in Kozier Fundamentals.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Mental Health Nursing',
    'General Mental'
) ON CONFLICT (stem, cadre) DO NOTHING;

