    difficulty,
    unit,
    topic
) VALUES (
    'A nurse using Maslows hierarchy of needs would indicate one of the following as a priority Nursing diagnosis:-',
    'Ineffective coping',
    'Risk for infection',
    'Altered comfort',
    'Ineffective breathing pattern',
    'D',
    'By Maslow''s hierarchy, physiological needs take priority, and oxygenation/breathing is the most basic survival need. Ineffective breathing pattern therefore ranks above infection risk, comfort and coping as the priority nursing diagnosis, per nursing process fundamentals.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Mental Health Nursing',
    'General Mental'
) ON CONFLICT (stem, cadre) DO NOTHING;

INSERT INTO questions (
    stem,
    option_a,
