    status,
    difficulty,
    unit,
    topic
) VALUES (
    'A client with acute leukemia is admitted to the oncology unit. Which of the following would be most important for the nurse to inquire:-',
    '"Have you lost weight recently?"',
    '"Have you noticed changes in your alertness?"',
    '"Have you noticed a change in sleeping habits recently?"',
    '"Have you had a respiratory infection in the last 6 months?"',
    'D',
    'In acute leukaemia, abnormal proliferation of immature leukocytes causes neutropenia and profound immunosuppression, making infection the leading cause of morbidity and mortality. Assessing for recent/recurrent respiratory infections is most important to guide protective measures, per Brunner & Suddarth oncology nursing.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Medical-Surgical Nursing',
    'General Medical-Surgical'
) ON CONFLICT (stem, cadre) DO NOTHING;

INSERT INTO questions (
    stem,
    option_a,
    option_b,
    option_c,
    option_d,
    correct_option,
    rationale,
    cadre,
    paper,
    exam_year,
    status,
    difficulty,
    unit,
    topic
) VALUES (
    'The nurse is admitting a client with Guillain-Barre syndrome to the nursing unit. The client has ascending paralysis to the level of the waist. Knowing the complications of the disorder, the nurse should bring which most essential items into the client’s room:-',
    'Nebulizer and pulse oximeter',
    'Blood pressure cuff and flashlight',
    'Flashlight and incentive spirometer',
    'Electrocardiographic monitoring electrodes and intubation tray',
    'A',
    'Ascending paralysis in Guillain-Barre syndrome threatens the respiratory (diaphragmatic) muscles, so respiratory monitoring and support are the most essential preparations. A pulse oximeter continuously monitors oxygenation while a nebulizer supports airway management; per Brunner & Suddarth neurological nursing, respiratory function is the priority in GBS. This is the standard keyed answer.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Anatomy & Physiology',
    'General Anatomy'
) ON CONFLICT (stem, cadre) DO NOTHING;

INSERT INTO questions (
    stem,
    option_a,
    option_b,
    option_c,
    option_d,
    correct_option,
    rationale,
    cadre,
    paper,
    exam_year,
    status,
    difficulty,
    unit,
    topic
) VALUES (
    'Based on the mechanism of action, the nurse would be right to expect that in this group of antibiotics patient may also have anemia:-',
    'Tetracyclins',
    'Carbapenems',
    'Sulfonamide',
    'Penicillin',
    'C',
    'Sulfonamides can cause haemolytic anaemia (especially in G6PD deficiency) and megaloblastic/aplastic anaemia through interference with folate metabolism and oxidative haemolysis. Chloramphenicol is the classic anaemia-causer, but among these options sulfonamides are the recognised cause of drug-induced anaemia (Kenya Pharmacology guidelines; Brunner & Suddarth).',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Pharmacology',
    'General Pharmacology'
) ON CONFLICT (stem, cadre) DO NOTHING;

