    status,
    difficulty,
    unit,
    topic
) VALUES (
    'Examination of a patient in a supine position reveal distended jugular veins from the base of the neck to the angle of the jaw. This finding indicates:-',
    'Decreased venous return',
    'Increased central venous pressure',
    'Increased pulmonary artery capillary pressure',
    'Left-sided heart failure',
    'B',
    'Jugular venous distension extending to the angle of the jaw in a supine (and even in an elevated) position reflects elevated central venous/right atrial pressure, indicating right-sided heart failure or fluid overload. This is the direct clinical correlate of raised CVP (Brunner & Suddarth Medical-Surgical Nursing).',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Anatomy & Physiology',
    'General Anatomy'
) ON CONFLICT (stem, cadre) DO NOTHING;

INSERT INTO questions (
    stem,
    option_a,
