    exam_year,
    status,
    difficulty,
    unit,
    topic
) VALUES (
    'The pain in acute suppurative otitis media is more severe at:-',
    'Night',
    'Morning',
    'Mid-day',
    'All the day',
    'A',
    'In acute suppurative otitis media the earache is characteristically worse at night because recumbency increases venous congestion and middle-ear pressure, intensifying the throbbing pain. This is standard ENT clinical teaching (Brunner & Suddarth).',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Medical-Surgical Nursing',
    'General Medical-Surgical'
) ON CONFLICT (stem, cadre) DO NOTHING;

INSERT INTO questions (
    stem,
    option_a,
