    status,
    difficulty,
    unit,
    topic
) VALUES (
    'A hydrophilic drug:-',
    'Has low ability to penetrate through the cell membrane lipids',
    'Penetrates through cell membranes via endocytosis',
    'Easily penetrates through blood-brain barrier',
    'Is highly reabsorbed in the renal tubules',
    'A',
    'Hydrophilic (water-soluble, often ionised) drugs do not dissolve readily in the lipid bilayer, so they penetrate cell membranes poorly and cross the blood-brain barrier poorly. They also are not highly reabsorbed in renal tubules. This is basic pharmacokinetics (Kenya Pharmacology guidelines).',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Community Health Nursing',
    'General Community'
) ON CONFLICT (stem, cadre) DO NOTHING;

