    status,
    difficulty,
    unit,
    topic
) VALUES (
    'An example of a non-modifiable risk factor for cardiac disease is;',
    'Use of oral contraceptives',
    'Post-menopause',
    'Diabetes mellitus',
    'High body mass index',
    'B',
    'Non-modifiable cardiac risk factors are those that cannot be changed (age, sex, family history, menopausal/hormonal status related to age). Post-menopause is age/sex-related and cannot be altered, whereas oral contraceptive use, diabetes and high BMI are modifiable (Brunner & Suddarth; Kenya MOH cardiovascular guidelines).',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Pharmacology',
    'General Pharmacology'
) ON CONFLICT (stem, cadre) DO NOTHING;

