) VALUES (
    'Clinical Manifestation of hyperthyroidism include:-',
    'Hypothermia, weight gain, constipation.',
    'Slurred speech, tachycardia, easy bruising.',
    'Increased appetite, weight gain, reduced peristalsis.',
    'Weight loss, palpitations, and menstrual disturbances.',
    'D',
    'Hyperthyroidism produces a hypermetabolic state: weight loss despite increased appetite, palpitations/tachycardia, heat intolerance and menstrual irregularities (oligomenorrhoea). The other options describe hypothyroid features (weight gain, constipation, hypothermia) (Brunner & Suddarth Medical-Surgical Nursing).',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Medical-Surgical Nursing',
    'General Medical-Surgical'
) ON CONFLICT (stem, cadre) DO NOTHING;

