    difficulty,
    unit,
    topic
) VALUES (
    'A patient has just received 30 mg of codeine by mouth for pain. Five minutes later the patient gets an episode of vomiting. What would be your first nursing intervention;',
    'Counsel the patient',
    'Observe the emesis',
    'Call the physician',
    'Remedicate the patient',
    'B',
    'The first nursing action is to assess/observe the vomitus to determine whether the codeine tablet was expelled before deciding whether re-medication is needed. Assessment precedes intervention in the nursing process, and this guides whether the dose was retained (Kozier Fundamentals of Nursing).',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Mental Health Nursing',
    'General Mental'
) ON CONFLICT (stem, cadre) DO NOTHING;

