    status,
    difficulty,
    unit,
    topic
) VALUES (
    'Medical management of the client with diverticulitis should include which of the following treatments:-',
    'Increased fiber in diet',
    'Reduced fluid intake',
    'Exercise to increase intra-abdominal pressure',
    'Administration of antibiotics',
    'D',
    'Acute diverticulitis (inflamed/infected diverticula) is managed with antibiotics, bowel rest and a LOW-fibre/clear-liquid diet during the acute phase; high-fibre diet is for prevention, not acute treatment. Reduced fluids and increasing intra-abdominal pressure are contraindicated (Brunner & Suddarth Medical-Surgical Nursing).',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Community Health Nursing',
    'General Community'
) ON CONFLICT (stem, cadre) DO NOTHING;

