    'Assess CAB and provide resuscitation first if needed before immobilization',
    'D',
    'In first aid the primary survey (Circulation-Airway-Breathing / life over limb) takes priority; resuscitation needs are addressed while maintaining manual in-line neck stabilisation, never extending or realigning the neck. Reference: Kenya First Aid / BLS guidelines.',
