) VALUES (
    'A client has signs of increased intracranial pressure (ICP). Which of the following is an early indicator of deterioration in the client’s condition:-',
    'Widening pulse pressure',
    'Decrease in pulse rate',
    'Dilated fixed pupils',
    'Decrease in level of consciousness',
    'D',
    'A declining level of consciousness is the earliest and most sensitive sign of rising ICP. Widening pulse pressure, bradycardia (Cushing''s triad) and fixed dilated pupils are late, ominous signs. Reference: Brunner & Suddarth Medical-Surgical Nursing.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Medical-Surgical Nursing',
