    'Incision site',
    'Respiration',
    'Level of pain',
    'The tubes attached',
    'B',
    'On receiving a post-operative patient, airway/breathing (respiration) is the immediate ABC priority, especially given anaesthetic-related respiratory depression. Incision, pain and tubes are assessed after airway/breathing are secured. Reference: Brunner & Suddarth; peri-operative nursing.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
