    difficulty,
    unit,
    topic
) VALUES (
    'The most appropriate intervention for a casualty with an open fracture of the lower limb would be to:-',
    'Lay the casualty down and lower both legs',
    'Elevate the head and apply pressure on the fracture site',
    'Apply direct pressure on the wound and raise the legs',
    'Apply pressure around the wound and support limb',
    'D',
    'For an open fracture with bleeding, apply pressure around (not directly on) the protruding bone/wound to control haemorrhage, then immobilise and support the limb. Direct pressure on the fracture or lowering/raising legs is inappropriate. Reference: Kenya First Aid guidelines.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Anatomy & Physiology',
    'General Anatomy'
) ON CONFLICT (stem, cadre) DO NOTHING;

