    difficulty,
    unit,
    topic
) VALUES (
    'A child with Wilms’ tumor presents with:-',
    'Gross hematuria',
    'Dysuria',
    'Nausea and vomiting',
    'An abdominal mass',
    'D',
    'Wilms'' tumour (nephroblastoma) classically presents as a painless, unilateral abdominal/flank mass discovered in a young child, often incidentally. Haematuria may occur but the hallmark presenting feature is the abdominal mass. Reference: Kenya Basic Paediatric Protocols; paediatric oncology.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Paediatric Nursing',
    'General Paediatric'
) ON CONFLICT (stem, cadre) DO NOTHING;

