    status,
    difficulty,
    unit,
    topic
) VALUES (
    'When assessing a patient for acute glaucoma, you would expect to find:-',
    'Clear cornea.',
    'Constricted pupil.',
    'Marked blurring of vision.',
    'Watery occular discharge.',
    'C',
    'Acute angle-closure glaucoma presents with sudden severe eye pain, marked blurring of vision with halos, a cloudy/steamy (hazy) cornea and a fixed mid-dilated pupil. Of the options, marked blurring of vision is the expected finding; the cornea is hazy (not clear) and the pupil dilated (not constricted). Reference: Brunner & Suddarth ophthalmic nursing.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Medical-Surgical Nursing',
    'General Medical-Surgical'
) ON CONFLICT (stem, cadre) DO NOTHING;

INSERT INTO questions (
    stem,
    option_a,
    option_b,
    option_c,
    option_d,
    correct_option,
    rationale,
    cadre,
    paper,
    exam_year,
    status,
    difficulty,
    unit,
    topic
) VALUES (
    'A patient is to receive 1,000 mL of Normal Saline over 8 hours. The Intravenous administration set has a drop factor of 20 drops per mL. The drip rate in drops per minute will be set at:-',
    '25 drops/min',
    '42 drops/min',
    '50 drops/min',
    '100 drops/min',
    'B',
    'Drip rate = (volume x drop factor) / time in minutes = (1000 mL x 20) / (8 x 60) = 20000/480 = 41.6 ~ 42 drops/min. This is the standard IV flow calculation per Kozier/Brunner.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
