    'The most common cause of recto-vaginal fistula is:-',
    'Obstetrical',
    'Irradiation of the pelvis',
    'Carcinoma',
    'Endometriosis',
    'A',
    'The most common cause of rectovaginal fistula is obstetric trauma, particularly obstructed/prolonged labour and third/fourth degree perineal tears, which is highly relevant in the Kenyan setting. This is consistent with Myles Textbook for Midwives and Kenya EmONC guidelines.',
