) VALUES (
    'A nursing intervention that is most appropriate to decrease post-operative edema and pain following an inguinal herniorraphy is:-',
    'Applying a truss to the hernia site',
    'Allowing the patient to stand to void',
    'Supporting incision during coughing',
    'Applying a scrotal support with ice bag',
    'D',
    'Following inguinal herniorrhaphy, scrotal support with an ice bag reduces post-operative scrotal/inguinal edema and pain by minimizing swelling and providing support, per Brunner & Suddarth surgical nursing. Supporting the incision during coughing prevents dehiscence but does not specifically decrease edema.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Surgical Nursing',
    'General Surgical'
) ON CONFLICT (stem, cadre) DO NOTHING;

