    'Hypercalcemia resulting from hyperpituitarism.',
    'Hypocalcemia resulting from hypoparathyroidism.',
    'Hypocalcemia resulting from hypothyroidism.',
    'C',
    'Chvostek''s sign (facial twitch on tapping the facial nerve) indicates neuromuscular irritability due to hypocalcemia, classically from hypoparathyroidism (e.g., after thyroidectomy). This is standard per Brunner & Suddarth.',
    'KRCHN',
