    status,
    difficulty,
    unit,
    topic
) VALUES (
    'Calcium gluconate should be readily available for a patient after thyroidectomy because:-',
    'The patient may experience tetany due to destruction of parathyroid glands.',
    'There is risk for respiratory distress caused by hematoma .',
    'Patients may become hypoglycemic due to inability to swallow.',
    'To correct hypercalcaemia that may occur due to reduced urinary output.',
    'A',
    'Inadvertent removal or damage of the parathyroid glands during thyroidectomy causes hypocalcemia leading to tetany; calcium gluconate must be readily available to treat this emergency. This is standard post-thyroidectomy nursing care per Brunner & Suddarth.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Anatomy & Physiology',
    'General Anatomy'
) ON CONFLICT (stem, cadre) DO NOTHING;

