    topic
) VALUES (
    'You are doing a digital rectal examination and you want to palpate the prostate gland; you will palpate the prostate on the:-',
    'Anterior wall of the rectum',
    'Lateral wall of the rectum',
    'Posterior wall of the rectum',
    'Proximal part of the rectum',
    'A',
    'During digital rectal examination the prostate gland is palpated on the anterior wall of the rectum, as it lies just anterior to the rectum below the bladder. This is standard clinical examination anatomy per Brunner & Suddarth.',
    'KRCHN',
    'Paper I',
