INSERT INTO questions (
    stem,
    option_a,
    option_b,
    option_c,
    option_d,
    correct_option,
    rationale,
    cadre,
    paper,
    exam_year,
    status,
    difficulty,
    unit,
    topic
) VALUES (
    'A 55-year-old man complaints that he sometimes has sudden pain on one side of his face. It lasts up to 2 minutes. The pain is excruciating and feels like an “electric shock”. He states it happens when he shaves and sometimes when he is chewing food. Upon physical exam, you notice the area of the face he points to is the area of distribution of 5th cranial nerve. He is otherwise healthy and does not take any medications. You ask him if he has ever had shingles and says no. The most likely diagnosis is:-',
    'Tic dolourex',
    'Cluster headache',
    'Bells palsy - cranial nerve 7',
    'Temporomandibular joint dysfunction',
    'A',
    'Trigeminal neuralgia (tic douloureux) is characterised by sudden, severe, electric-shock-like paroxysms of pain along the distribution of the 5th cranial nerve, triggered by activities such as shaving, chewing or touching the face. The classic trigger points and unilateral facial distribution distinguish it from Bell''s palsy (motor weakness) and cluster headache. Reference: Brunner & Suddarth Medical-Surgical Nursing.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Pharmacology',
    'General Pharmacology'
) ON CONFLICT (stem, cadre) DO NOTHING;

