    exam_year,
    status,
    difficulty,
    unit,
    topic
) VALUES (
    'Causes of sensorineural hearing loss include:-',
    'Aging, impacted cerumen.',
    'Ototoxic drugs, brain tumours.',
    'Chronic exposure to loud noise, otitis media.',
    'Mumps, perforation of tympanic membrane.',
    'B',
    'Sensorineural hearing loss results from damage to the cochlea or auditory nerve, caused by ototoxic drugs (aminoglycosides, furosemide) and acoustic/brain tumours. Impacted cerumen, otitis media and tympanic perforation cause conductive loss. Reference: Brunner & Suddarth.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Pharmacology',
    'General Pharmacology'
) ON CONFLICT (stem, cadre) DO NOTHING;

