) VALUES (
    'A patient has a visual acuity of 20/200. This means that a person can see an object:-',
    '20 feet away',
    '100 feet away.',
    'Either 20 or 200 feet away',
    '200 feet away.',
    'A',
    'Visual acuity of 20/200 means the person sees at 20 feet what a person with normal vision sees at 200 feet. The first number (20 feet) is the standard testing distance at which the patient reads the chart. Reference: Kozier/Brunner & Suddarth ophthalmic assessment.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
