) VALUES (
    'The nurse explains to the mother of a 13-year-old admitted to hospital in a sickle cell crisis that the local tissue damage has been caused by the following:-',
    'Lack of oxygen in red blood cells',
    'Obstruction to circulation',
    'Autoimmune reaction complicated by hypoxia',
    'Elevated serum bilirubin concentration',
    'B',
    'In sickle cell crisis, sickled (rigid, crescent-shaped) red cells clump and occlude small vessels, causing vaso-occlusion. This obstruction to circulation produces local ischaemia, tissue hypoxia and infarction (tissue damage). Reference: Kenya Basic Paediatric Protocols; Brunner & Suddarth.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Medical-Surgical Nursing',
    'General Medical-Surgical'
) ON CONFLICT (stem, cadre) DO NOTHING;

