    unit,
    topic
) VALUES (
    'The rationale for use of angiotensin converting enzyme inhibitors particularly in treating patients with chronic kidney disease is;-',
    'Increase proteinuria and stabilize renal function',
    'Diminish proteinuria and stabilize renal function',
    'Increase urine output and stabilize renal function',
    'Increase loss of albumin in urine',
    'B',
    'ACE inhibitors reduce intraglomerular pressure by dilating the efferent arteriole, thereby diminishing proteinuria and slowing progression of chronic kidney disease (renoprotection). Reference: Kenya MOH clinical guidelines; Brunner & Suddarth.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Medical-Surgical Nursing',
    'General Medical-Surgical'
) ON CONFLICT (stem, cadre) DO NOTHING;

