    'B',
    'Dumping syndrome is a well-recognised complication of gastric surgery (gastrectomy/gastric resection), where rapid emptying of hyperosmolar chyme into the jejunum causes vasomotor and GI symptoms. Reference: Brunner & Suddarth Medical-Surgical Nursing.',
    'KRCHN',
