) VALUES (
    'You are providing first aid to a client with frostbite on the feet. The second priority in the order of interventions would is,',
    'Immerse the feet in warm water at about 40 0 C',
    'Remove the victim from the cold environment',
    'Administer a pain medication such as paracetamol',
    'Apply a loose sterile bulky dressing on the feet',
    'A',
    'The first priority in frostbite first aid is removing the victim from the cold environment; the second priority is rapid rewarming by immersion in warm water at about 37-40 degrees C. Rewarming precedes analgesia and dressing. Reference: Brunner & Suddarth emergency care.',
    'KRCHN',
    'Paper I',
    2026,
