    'Acute pain related to biologic and chemical factors',
    'Anxiety related to change in the health status.',
    'Anxiety related to fear of the prognosis',
    'Risk of side effects related to medical therapy',
    'A',
    'Migraine is defined by severe headache pain; using Maslow/ABC prioritisation, acute pain is the priority nursing diagnosis over anxiety or risk diagnoses. Pain relief is the immediate patient need. Reference: Brunner & Suddarth; nursing process.',
    'KRCHN',
