    status,
    difficulty,
    unit,
    topic
) VALUES (
    'A male client has an impairment of cranial nerve II. Specific to this impairment, the nurse would plan to do which of the following to ensure clients to ensure client safety:',
    'Speak loudly to the client',
    'Test the temperature of the shower water',
    'Check the temperature of the food on the delivery tray',
    'Provide a clear path for ambulation without obstacles',
    'D',
    'Cranial nerve II (optic nerve) governs vision. Impairment causes visual deficit, so the priority safety measure is ensuring a clear, obstacle-free path to prevent falls and injury during ambulation. Speaking loudly (CN VIII) and testing water/food temperature (sensory) are unrelated to vision (Brunner & Suddarth).',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Community Health Nursing',
    'General Community'
) ON CONFLICT (stem, cadre) DO NOTHING;

