    difficulty,
    unit,
    topic
) VALUES (
    'The nurse is assigned to care for a female client with complete right-sided hemiparesis. The nurse plans care knowing that this condition;',
    'The client has complete bilateral paralysis of arms and legs',
    'The client has weakness on the right side of the body including the face and tongue',
    'The client has lost the ability to move the right arm but is able walk independently',
    'The client has lost the ability to move the left arm but is able to walk independently',
    'B',
    'Hemiparesis means weakness (not total paralysis) of one side of the body. Right-sided hemiparesis involves weakness of the right arm, leg, face and tongue, typically from a left-hemisphere stroke. Complete paralysis would be hemiplegia (Brunner & Suddarth).',
    'KRCHN',
    'Paper I',
