    'Give the patient solid food',
    'Administering clear fluids only',
    'An enema to prepare bowel for surgery',
    'Administering intravenous antibiotics',
    'D',
    'A ruptured appendix causes peritonitis; pre-operative care requires IV broad-spectrum antibiotics to control infection, IV fluids, and NPO status. Enemas are contraindicated as they may worsen perforation/peritonitis, and the patient must be kept nil by mouth, not given solids or fluids (Brunner & Suddarth).',
    'KRCHN',
    'Paper I',
