    'Chronic bronchitis, pleurisy, bronchiectasis',
    'A',
    'COPD encompasses chronic bronchitis, emphysema and peripheral (small) airways disease, characterised by persistent airflow limitation. Empyema, pulmonary embolism, pleurisy and bronchiectasis are not classified as COPD (Brunner & Suddarth).',
    'KRCHN',
