    status,
    difficulty,
    unit,
    topic
) VALUES (
    'During the analysis of cerebral spinal fluid in the diagnosis of meningitis .The type of meningitis where there is cerebral spinal fluid glucose is normal and present of lymphocytes is:-',
    'Viral meningitis',
    'Tuberculosis meningitis',
    'Meningococcal meningitis',
    'Pneumococcal meningitis',
    'A',
    'In viral (aseptic) meningitis, CSF glucose is normal with a lymphocytic (mononuclear) pleocytosis. Bacterial meningitis (meningococcal, pneumococcal) shows low glucose with neutrophils; TB meningitis shows low glucose with lymphocytes (Kenya clinical guidelines; Brunner & Suddarth).',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
