    'Failure to thrive, tenesmus',
    'Projectile vomiting, colicky abdominal pains',
    'Constipation, olive-like mass in upper abdomen',
    'Observable peristaltic movements, diarrhea',
    'B',
    'Pyloric stenosis classically presents with non-bilious projectile vomiting after feeds, hunger/colicky discomfort, visible peristalsis and a palpable olive-like mass. Among the options, projectile vomiting with colicky pain is the correct manifestation set; constipation with olive mass mixes a correct sign with an atypical one (Kenya Basic Paediatric Protocols; Nelson).',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
