    'NSAIDS, Allopurinol.',
    'B',
    'Chronic gouty arthritis management targets serum urate lowering: allopurinol (xanthine oxidase inhibitor) reduces uric acid production and probenecid (uricosuric) enhances excretion. Colchicine and NSAIDs treat acute attacks rather than chronic disease (Kenya therapeutic guidelines; Brunner & Suddarth).',
    'KRCHN',
