    status,
    difficulty,
    unit,
    topic
) VALUES (
    'Furuncles are commonly caused by:-',
    'Streptococcus pyogenes.',
    'Staphylococcus aureus.',
    'Pseudomonas aeroginosa.',
    'Clostridium tetani',
    'B',
    'Furuncles (boils) are deep hair-follicle infections most commonly caused by Staphylococcus aureus. Streptococcus pyogenes typically causes cellulitis/erysipelas, Pseudomonas causes folliculitis in other settings, and Clostridium tetani causes tetanus (Brunner & Suddarth; Kenya IPC guidelines).',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Medical-Surgical Nursing',
    'General Medical-Surgical'
) ON CONFLICT (stem, cadre) DO NOTHING;

INSERT INTO questions (
    stem,
    option_a,
    option_b,
    option_c,
    option_d,
    correct_option,
    rationale,
    cadre,
    paper,
    exam_year,
    status,
    difficulty,
    unit,
    topic
) VALUES (
    'A patient Kante, 16 years old is brought to the Emergency department with history of sodium hypochloride/JIK spill on the left eye 5 minutes ago. The first most appropriate Nurse action would be:-',
    'Immediately refer to an ophthalmologist for review',
    'Administer topical antibiotics and analgesics',
    'Test for Visual Acuity to check extent of damage',
    'Patch the eye after irrigation with clean water',
    'D',
    'For a chemical (alkaline JIK/sodium hypochlorite) eye burn, the immediate priority is copious irrigation of the eye with clean water or saline to dilute and remove the corrosive agent and limit tissue damage, per emergency ophthalmic first-aid guidelines. Of the given options, irrigation is the only one that appears, though patching should not routinely follow. Referral, acuity testing and medication all come after decontamination. Brunner & Suddarth; Kenya emergency care guidelines.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Community Health Nursing',
    'General Community'
) ON CONFLICT (stem, cadre) DO NOTHING;

INSERT INTO questions (
