    option_a,
    option_b,
    option_c,
    option_d,
    correct_option,
    rationale,
    cadre,
    paper,
    exam_year,
    status,
    difficulty,
    unit,
    topic
) VALUES (
    'Drug route of administration associated with first-pass metabolism is:-',
    'Intravenous',
    'Intramuscular',
    'Sublingual',
    'Oral',
    'D',
    'Orally administered drugs are absorbed from the GI tract into the portal circulation and pass through the liver before reaching systemic circulation, undergoing first-pass (presystemic) metabolism. IV, IM and sublingual routes bypass the portal circulation and avoid first-pass effect. Basic pharmacology (Kenya Pharmacology guidelines; Brunner & Suddarth).',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Pharmacology',
    'General Pharmacology'
) ON CONFLICT (stem, cadre) DO NOTHING;

INSERT INTO questions (
    stem,
    option_a,
    option_b,
    option_c,
    option_d,
    correct_option,
    rationale,
    cadre,
    paper,
    exam_year,
    status,
    difficulty,
    unit,
    topic
) VALUES (
    'Management of Cushing’s syndrome include:-',
    'Administration of spironolactone, daily weight taking, fluid restriction',
    'Monitoring blood glucose levels, providing a high sodium diet, antibiotic therapy',
    'Assessing signs of hyperkalemia, input and output monitoring, encouraging high protein diet',
    'Encourage ambulation, plenty of fluids, H2 receptor antagonist therapy',
    'A',
    'Cushing''s syndrome causes excess cortisol with sodium/water retention, oedema, hypertension and hypokalaemia; management includes a potassium-sparing agent such as spironolactone, daily weight monitoring and fluid restriction to control fluid overload, plus a low-sodium diet. The other options recommend inappropriate measures (high sodium, high fluids). Brunner & Suddarth Medical-Surgical Nursing.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Community Health Nursing',
    'General Community'
) ON CONFLICT (stem, cadre) DO NOTHING;

