    exam_year,
    status,
    difficulty,
    unit,
    topic
) VALUES (
    'Major risk factors for cerebral vascular accident include:-',
    'Trauma, high alcohol intake, positive family history',
    'Arterial hypertension, trauma, hyperlipidemia',
    'Arterial hypertension, hyperlipidemia, cigarette smoking',
    'Positive family history, hyperlipidemia, high alcohol intake',
    'C',
    'The major modifiable risk factors for cerebrovascular accident (stroke) are hypertension (the single most important), hyperlipidaemia and cigarette smoking. Trauma and family history are not the principal risk factors, making the combination in option C the most correct. Brunner & Suddarth; Kenya MOH stroke guidelines.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Medical-Surgical Nursing',
    'General Medical-Surgical'
) ON CONFLICT (stem, cadre) DO NOTHING;

INSERT INTO questions (
