    option_d,
    correct_option,
    rationale,
    cadre,
    paper,
    exam_year,
    status,
    difficulty,
    unit,
    topic
) VALUES (
    'The client being seen in a physician’s office has just been scheduled for a barium swallow the next day. The nurse writes down which of the following instructions for the client to follow before the test:-',
    'Eat regular supper and breakfast',
    'Fast for 8 hours before the test',
    'Monitor own bowel movement pattern for constipation',
    'Continue to take all oral medications as scheduled',
    'B',
    'A barium swallow requires the client to be NPO (fasting) for about 8 hours before the procedure so the upper GI tract is empty for clear visualisation. Post-procedure the nurse monitors bowel patterns for constipation from retained barium, but the pre-test instruction is fasting. Brunner & Suddarth diagnostic nursing.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Medical-Surgical Nursing',
    'General Medical-Surgical'
) ON CONFLICT (stem, cadre) DO NOTHING;

INSERT INTO questions (
    stem,
    option_a,
    option_b,
    option_c,
    option_d,
    correct_option,
    rationale,
    cadre,
    paper,
    exam_year,
    status,
    difficulty,
    unit,
    topic
) VALUES (
    'A client arrives in the emergency department after a motor vehicle accident. Nursing assessment findings include BP 80/34, pulse rate 120, and respirations 20. Which is the client’s most appropriate priority nursing diagnosis?',
    'Alteration in cerebral tissue perfusion',
    'Fluid volume deficit',
    'Ineffective airway clearance',
    'Alteration in sensory perception',
    'B',
    'The findings (BP 80/34, pulse 120, tachycardia) after trauma indicate hypovolaemic shock from blood loss, so fluid volume deficit is the priority nursing diagnosis needing fluid resuscitation. Airway is patent (respirations 20 and unlaboured) and there is no evidence of airway compromise, so ABC is satisfied and circulation/volume takes priority here. Brunner & Suddarth emergency/shock nursing.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Midwifery',
    'General Midwifery'
) ON CONFLICT (stem, cadre) DO NOTHING;

INSERT INTO questions (
    stem,
    option_a,
    option_b,
    option_c,
    option_d,
    correct_option,
    rationale,
    cadre,
    paper,
    exam_year,
    status,
    difficulty,
    unit,
    topic
) VALUES (
    'The best nursing position for a patient following total hip replacement would be.',
    'Sims',
    'Prone',
    'Semi-fowlers',
    'Trendelenburg',
    'C',
    'After total hip replacement the hip must not be flexed beyond 90 degrees and the leg kept in abduction with neutral rotation to prevent dislocation. Of the options, semi-Fowler''s (limited head elevation) is the safest tolerable position; prone, Sims and Trendelenburg risk hip adduction/malposition or excessive flexion. Brunner & Suddarth orthopaedic nursing.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Medical-Surgical Nursing',
    'General Medical-Surgical'
) ON CONFLICT (stem, cadre) DO NOTHING;

INSERT INTO questions (
    stem,
    option_a,
    option_b,
    option_c,
    option_d,
    correct_option,
    rationale,
    cadre,
    paper,
    exam_year,
    status,
    difficulty,
    unit,
    topic
) VALUES (
    'In regard to Coronary artery disease (CAD). Select the most correct statement: -',
    'Does not present with high levels of cardiac enzymes like in myocardial infarction',
    'Sudden cardiac death is an event that is due to a decrease in blood supply from CAD',
    'Positron emission tomography (PET) is the definitive diagnostic procedure for CAD',
    'Long acting nitrates e.g. P.O isosorbide dinitrate 50-100 mg QID can be given',
    'B',
    'Coronary artery disease reduces myocardial blood supply and is the leading cause of sudden cardiac death through fatal ischaemia and arrhythmia. The other statements are false: CAD can raise cardiac enzymes when ischaemia occurs, PET is not the definitive diagnostic test (coronary angiography is), and the stated nitrate dose is excessive/incorrect. Brunner & Suddarth cardiovascular nursing.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Pharmacology',
    'General Pharmacology'
) ON CONFLICT (stem, cadre) DO NOTHING;

INSERT INTO questions (
    stem,
    option_a,
    option_b,
    option_c,
    option_d,
    correct_option,
    rationale,
    cadre,
    paper,
    exam_year,
    status,
    difficulty,
    unit,
    topic
) VALUES (
    'The nurse has given suggestions to a client with trigeminal neuralgia about strategies to minimize episodes of pain. The nurse determines that the client needs further teaching if the client makes which statement:-',
    '“I will wash my face with cotton pads.”',
    '“I’ll have to start chewing on my unaffected side.”',
    '“I should not rinse my mouth if toothbrushing is painful.”',
    '“I should rinse my mouth if toothbrushing is painful.”',
    'A',
    'In trigeminal neuralgia any tactile facial stimulation, including washing the face with cotton pads, can trigger paroxysmal pain, so this statement indicates the client needs further teaching (Brunner & Suddarth). Correct self-care includes chewing on the unaffected side and rinsing the mouth when toothbrushing is painful, so options B and D reflect appropriate understanding. The statement showing a misconception is washing the face with cotton pads.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Medical-Surgical Nursing',
    'General Medical-Surgical'
) ON CONFLICT (stem, cadre) DO NOTHING;

