    status,
    difficulty,
    unit,
    topic
) VALUES (
    'The most common outcome of obstructed blood flow to the liver is:-',
    'Oesphageal varises',
    'Biliary cirrhosis',
    'Portal hypertension',
    'Liver cirrhosis',
    'C',
    'Obstruction of blood flow through the liver raises pressure in the portal venous system, producing portal hypertension, which is the direct and most common consequence. Oesophageal varices and ascites are downstream complications of the portal hypertension itself. Per Brunner & Suddarth Medical-Surgical Nursing.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Medical-Surgical Nursing',
    'General Medical-Surgical'
) ON CONFLICT (stem, cadre) DO NOTHING;

