    unit,
    topic
) VALUES (
    'An example of a local factor that affects wound healing is:-',
    'Desiccation',
    'Circulation',
    'Nutrition status',
    'Drug therapy',
    'A',
    'Desiccation (drying of the wound surface) is a local factor acting directly at the wound site that impairs epithelial migration and healing. Circulation, nutritional status and drug therapy are systemic factors. Per Kozier Fundamentals of Nursing and Brunner & Suddarth.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
