    exam_year,
    status,
    difficulty,
    unit,
    topic
) VALUES (
    'An patient’s X-ray shows accumulation of thick, purulent fluid within the pleural space with fibrin development. The most likely condition with the patient is;',
    'Stasis',
    'Pleurisy',
    'Empyema',
    'Atelectasis',
    'C',
    'Accumulation of thick, purulent fluid in the pleural space with fibrin deposition defines empyema. Pleurisy is inflammation of the pleura without pus, and atelectasis is lung collapse. Per Brunner & Suddarth Medical-Surgical Nursing.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Medical-Surgical Nursing',
    'General Medical-Surgical'
) ON CONFLICT (stem, cadre) DO NOTHING;

INSERT INTO questions (
    stem,
    option_a,
    option_b,
    option_c,
    option_d,
    correct_option,
    rationale,
    cadre,
    paper,
    exam_year,
    status,
    difficulty,
    unit,
    topic
) VALUES (
    '65-year-old man undergoes total knee revision without complication. Routine intraoperative cultures are submitted that are positive for growth of coagulase negative staphylococcus at 48 hours postoperative in 3 of 5 specimens. The patient is afebrile and his wound is dry. Appropriate treatment should include:-',
    'No further antibiotic therapies',
    'Irrigation and debridement with retention of the components',
    'Six weeks of parenteral antibiotics',
    'Irrigation and debridement with removal of components',
    'C',
    'Growth of coagulase-negative staphylococcus in 3 of 5 intraoperative cultures meets the threshold for a genuine (not contaminant) periprosthetic infection, indicating deep infection requiring treatment. With well-fixed components and no acute wound breakdown, standard management is component retention with a course of parenteral antibiotics (approximately six weeks). Per orthopaedic/surgical infection guidelines.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Pharmacology',
    'General Pharmacology'
) ON CONFLICT (stem, cadre) DO NOTHING;

