    exam_year,
    status,
    difficulty,
    unit,
    topic
) VALUES (
    'Myopia is commonly caused by:-',
    'Too short eye ball',
    'Decreased curvature of the lens',
    'A backward displacement of the lens on the globe',
    'Increased retroactive ludices of the cornea, lens and aqueous',
    'D',
    'Myopia (near-sightedness) results from light focusing in front of the retina, caused by an excessively long eyeball or increased refractive power (refractive indices/curvature) of the cornea and lens. Among the options, increased refractive index of the ocular media produces this excess convergence. A too-short eyeball causes hyperopia, not myopia. Per Brunner & Suddarth.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Medical-Surgical Nursing',
    'General Medical-Surgical'
) ON CONFLICT (stem, cadre) DO NOTHING;

