    paper,
    exam_year,
    status,
    difficulty,
    unit,
    topic
) VALUES (
    'A client has autoimmune thrombocytopenic purpura. To determine the client''s response to treatment, the nurse would monitor:-',
    'Platelet count',
    'White blood cell count',
    'Potassium levels',
    'Partial prothrombin time',
    'A',
    'Autoimmune (idiopathic) thrombocytopenic purpura is characterised by immune destruction of platelets; response to treatment (steroids, IVIG, splenectomy) is evaluated by a rising platelet count. WBC, potassium and PTT do not reflect the disorder. Per Brunner & Suddarth Medical-Surgical Nursing.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Medical-Surgical Nursing',
    'General Medical-Surgical'
) ON CONFLICT (stem, cadre) DO NOTHING;

