    cadre,
    paper,
    exam_year,
    status,
    difficulty,
    unit,
    topic
) VALUES (
    'The nursing management of the patient with cholecystitis associated with cholelithiasis is based on the knowledge that:-',
    'A low-fat diet is recommended',
    'Gallstones once removed tend not to recur',
    'Meperidine is to be avoided in the management of pain',
    'The disorder can be successfully treated with oral bile salts that dissolve gallstones',
    'A',
    'In cholecystitis with cholelithiasis, a low-fat diet reduces gallbladder stimulation and pain. Gallstones can recur, meperidine is no longer specifically preferred but is not absolutely avoided, and oral bile salt dissolution is only rarely and partially effective. The reliable nursing knowledge is the low-fat dietary recommendation. Per Brunner & Suddarth.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Pharmacology',
    'General Pharmacology'
) ON CONFLICT (stem, cadre) DO NOTHING;

