    exam_year,
    status,
    difficulty,
    unit,
    topic
) VALUES (
    'A client is discharged home with a prescription for Coumadin (sodium warfarin). The client should be instructed to:-',
    'Have a Protime done monthly',
    'Eat more fruits and vegetables',
    'Drink more liquids',
    'Avoid crowds',
    'A',
    'Warfarin (Coumadin) requires regular monitoring of prothrombin time (PT/INR) to keep dosing within therapeutic range and prevent bleeding or clotting. Patients should also maintain consistent (not increased) vitamin K intake, so eating more green vegetables would interfere with control. Reference: Brunner & Suddarth Medical-Surgical Nursing; Kenya therapeutic guidelines.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Medical-Surgical Nursing',
    'General Medical-Surgical'
) ON CONFLICT (stem, cadre) DO NOTHING;

