    exam_year,
    status,
    difficulty,
    unit,
    topic
) VALUES (
    'A type of wound debridement where topical chemicals are used to break down and liquefy  wound debris is:-',
    'Autolytic',
    'Surgical',
    'Enzymatic',
    'Mechanical',
    'C',
    'Enzymatic debridement uses topical chemical/proteolytic enzymes applied to the wound to break down and liquefy necrotic debris. Autolytic uses the body''s own enzymes under moist dressings, surgical uses instruments, and mechanical uses physical force such as wet-to-dry dressings. Reference: Brunner & Suddarth wound care.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Surgical Nursing',
    'General Surgical'
) ON CONFLICT (stem, cadre) DO NOTHING;

