    status,
    difficulty,
    unit,
    topic
) VALUES (
    'A nurse anticipates that the type of traction that will be used for a 16 Kgs client with a fractured femur is:-',
    'Bryant’s traction',
    'Dunlop’s traction',
    'Weil sling',
    'Buck’s extension traction',
    'D',
    'For a 16 kg (older child/adolescent) with a fractured femur, Buck''s extension (skin traction) is appropriate. Bryant''s traction is reserved for young children under about 2 years or weighing under ~12–14 kg where both legs are suspended vertically. Reference: Kozier Fundamentals; orthopaedic nursing.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Paediatric Nursing',
    'General Paediatric'
) ON CONFLICT (stem, cadre) DO NOTHING;

