    difficulty,
    unit,
    topic
) VALUES (
    'Primary role of hydrochloric acid in the digestive process is to:-',
    'Break down carbohydrates into simple sugars',
    'Activate pepsinogen to pepsin',
    'Prevent mechanical injury to the stomach wall',
    'Emulsification of fats and fatty acids',
    'B',
    'Hydrochloric acid secreted by gastric parietal cells provides the acidic environment that converts inactive pepsinogen into active pepsin for protein digestion, and also kills ingested pathogens. It does not digest carbohydrates or emulsify fats (bile does that). Reference: Anatomy & Physiology (Tortora/Guyton).',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
