    'Pemphigus is an autoimmune blistering disorder characterized by flaccid vesicles and bullae of varying sizes that rupture easily, with a positive Nikolsky sign. The lesions are fluid-filled blisters rather than papules, macules or pustular nodules. Reference: Brunner & Suddarth dermatology.',
