    difficulty,
    unit,
    topic
) VALUES (
    'An adult patient weighing 120 kg has a 20% total body surface area burn. Using the modified parkland formula, how much total intravenous fluid should he receive in the first 8 hours:-',
    '2400 mL',
    '4800mL',
    '9600 mL',
    '10,800 ml',
    'B',
    'Parkland formula = 4 mL x weight (kg) x %TBSA = 4 x 120 x 20 = 9600 mL total in 24 hours, with half given in the first 8 hours = 4800 mL. Reference: Brunner & Suddarth burns management; Kenya emergency guidelines.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Pharmacology',
    'General Pharmacology'
) ON CONFLICT (stem, cadre) DO NOTHING;

