) VALUES (
    'Complications associated with Tracheo-oesophageal atresia include:-',
    'Pneumonia, malnutrition, intestinal obstruction',
    'Stenosis of the oesophagus, leakage into the mediastinum, intestinal obstruction.',
    'Abdominal distension, constipation,fitula formation',
    'Gastro-esophageal reflux, esophagus constriction, leakage into chest cavity.',
    'B',
    'Tracheo-oesophageal atresia/fistula predisposes to aspiration pneumonia and, following surgical repair, anastomotic stricture (oesophageal stenosis) and anastomotic leak into the mediastinum. Option B best captures oesophageal stenosis and mediastinal leakage as recognised complications. Reference: Kenya Basic Paediatric Protocols; paediatric surgery texts.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Surgical Nursing',
    'General Surgical'
) ON CONFLICT (stem, cadre) DO NOTHING;

