) VALUES (
    'Cerebral hemorrhage located under the dura matter is:-',
    'Epidural hematoma.',
    'Extradural hematoma.',
    'Intracerebral hematoma.',
    'Subdural hematoma',
    'D',
    'A subdural hematoma is a collection of blood located beneath (under) the dura mater, typically from torn bridging veins. Epidural/extradural hematomas lie above the dura, and intracerebral hematomas are within brain tissue (Brunner & Suddarth Medical-Surgical Nursing).',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Anatomy & Physiology',
    'General Anatomy'
) ON CONFLICT (stem, cadre) DO NOTHING;

