    difficulty,
    unit,
    topic
) VALUES (
    'For proper diagnosis and management of respiratory conditions, various diagnostic procedures can be performed. A procedure that utilizes a spirometer is: -',
    'Arterial blood gases',
    'Pulmonary function tests',
    'Pulse oximetry',
    'Serial blood gas analysis',
    'B',
    'Pulmonary function tests (spirometry) use a spirometer to measure lung volumes and airflow. Arterial blood gases, pulse oximetry and serial blood gas analysis do not use a spirometer (Brunner & Suddarth Medical-Surgical Nursing).',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
