) VALUES (
    'Reabsorption in the renal tubule occurs:-',
    'Passively to transport sugar and amino acids',
    'Actively to promote water reabsorption',
    'By the antidiuretic hormone decreasing permeability at the tubules',
    'Due to high aldosterone that reduces sodium excretion',
    'A',
    'Tubular reabsorption occurs by both active and passive mechanisms; glucose and amino acids are reabsorbed via carrier-mediated transport. Among these options the best fit is that reabsorption occurs to transport sugars and amino acids. ADH increases (not decreases) permeability to water, and aldosterone increases sodium reabsorption, making the other options incorrect (Guyton/Kozier physiology).',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Community Health Nursing',
    'General Community'
) ON CONFLICT (stem, cadre) DO NOTHING;

