    'Epinephrine',
    'D',
    'Epinephrine (adrenaline) is the first-line drug for anaphylactic shock, given IM 0.5 mg (1:1000). It reverses bronchospasm, vasodilation and hypotension. The other vasopressors are not the treatment of choice for anaphylaxis (Kenya MOH emergency guidelines; Brunner & Suddarth).',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
