    'Birth of the head',
    'D',
    'After the birth (delivery) of the head, before restitution and delivery of the shoulders, the midwife feels around the neck to check for a nuchal cord (cord around the neck). This is the recognised point for checking in the second stage of labour (Myles Textbook for Midwives; Kenya EmONC).',
    'KRCHN',
