) VALUES (
    'A ring of tight muscle that forms around the body or neck of fetus is:-',
    'Bundls’ ring',
    'Bundle of his',
    'Constriction ring',
    'Retraction ring',
    'C',
    'A constriction ring is a localised, persistent contraction/spasm of a ring of uterine muscle that forms around the fetal neck or body (often at a junction), typically due to uncoordinated uterine action. Bandl''s ring is a retraction ring seen in obstructed labour, distinct from a constriction ring. Per Myles Textbook for Midwives.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
