    difficulty,
    unit,
    topic
) VALUES (
    'When the chorion detaches from lower uterine segment due to increased intrauterine pressure and forms a sac of fluid that bulge downward into the internal os is called: -',
    'Rupture of membranes',
    'Formation of upper and lower uterine segments',
    'Formation of fore waters',
    'Intensity and resting tone',
    'C',
    'As the chorion detaches from the lower uterine segment and increased intrauterine pressure pushes fluid ahead of the presenting part into the internal os, the bulging bag of fluid is the forewaters. This is a normal mechanism of the first stage. Per Myles Textbook for Midwives.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Community Health Nursing',
    'General Community'
) ON CONFLICT (stem, cadre) DO NOTHING;

