    unit,
    topic
) VALUES (
    'Mechanical factors that facilitates progress of labour during first stage include:-',
    'General fluid pressure, foetal axis pressure',
    'Cervical dilatation, fundal dominance',
    'Polarity, cervical effacement',
    'Fundal dominance, fetal axis pressure',
    'A',
    'Mechanical factors aiding first-stage progress are general fluid pressure (even distribution of intrauterine pressure via the forewaters) and fetal axis pressure (force transmitted down the fetal long axis). Fundal dominance and polarity describe the physiology of contractions rather than mechanical factors, and cervical dilatation/effacement are effects. Per Myles Textbook for Midwives.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Midwifery',
    'General Midwifery'
) ON CONFLICT (stem, cadre) DO NOTHING;

