    status,
    difficulty,
    unit,
    topic
) VALUES (
    'If delivery occurs unexpectedly while the patient is on Heparin and excessive bleeding occurs, what is the appropriate initial intervention:-',
    'Administaration of tranexemic acid.',
    'Ligation of the hypogastric arteries.',
    'Infusion of fresh frozen plasma.',
    'Administration of protamine acetate.',
    'D',
    'Heparin-induced bleeding is reversed with protamine, which binds and neutralises heparin. Among the options this is the specific antidote for heparin, so it is the appropriate initial intervention. (Standard preparation is protamine sulphate; the option''s wording is the intended answer.) Per Kenya/standard pharmacology guidelines.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'easy',
    'Medical-Surgical Nursing',
    'General Medical-Surgical'
) ON CONFLICT (stem, cadre) DO NOTHING;

