    exam_year,
    status,
    difficulty,
    unit,
    topic
) VALUES (
    'A 33 year female at 37 weeks gestation confirmed by early sonography presents with moderate severe vaginal bleeding, she is noted to have placenta previa, which of the following is the best management for her :-',
    'Caesarian Section',
    'Expectant management',
    'Artificial rupture of membrane',
    'Give tocolytic drugs',
    'A',
    'At 37 weeks (term) with confirmed placenta praevia and moderate-to-severe vaginal bleeding, the definitive and safest management is delivery by caesarean section. Expectant/tocolytic management is only for preterm gestation with minimal bleeding, and ARM is contraindicated in praevia. Per Kenya EmONC/obstetric guidelines and Myles.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Midwifery',
    'General Midwifery'
) ON CONFLICT (stem, cadre) DO NOTHING;

