    status,
    difficulty,
    unit,
    topic
) VALUES (
    'The active management of third stage of labor in sequence include:-',
    'Control cord traction, massage uterus and administer uterotonic',
    'Administer uterotonic, massage uterus and control cord traction',
    'Control cord traction, administer uterotonic and massage uterus',
    'Administer uterotonic, controlled cord traction and massage uterus.',
    'D',
    'Active management of the third stage in correct sequence is: give a uterotonic (oxytocin within one minute of birth), controlled cord traction to deliver the placenta, then uterine massage after placental delivery. Per Kenya EmONC/AMTSL guidelines and WHO.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
