    unit,
    topic
) VALUES (
    'A nurse observation to a patient on heparin is:-',
    'Gentle movement in bed when pain subsides',
    'Monitor colour and amount of lochia',
    'Ensure protamine sulphate is available',
    'Continue breastfeeding',
    'C',
    'A key nursing responsibility for a patient on heparin is to keep the antidote, protamine sulphate, readily available in case of haemorrhage from over-anticoagulation. This is the safety-focused observation/precaution specific to heparin therapy. Per standard pharmacology/nursing references.',
    'KRCHN',
    'Paper I',
