    topic
) VALUES (
    'The maneuver used in the delivery of extended arms in shoulder dystocia is:-',
    'Rubin’s maneuver',
    'Roberts maneuver',
    'Burnmashall maneuver',
    'Loverset maneuver',
    'D',
    'Lovset''s manoeuvre is used to deliver extended (nuchal) arms, classically in breech delivery; the same rotational principle is applied to free extended arms. Rubin''s and Woods (screw) are internal rotation manoeuvres and McRoberts is positional for shoulder dystocia. Per Myles Textbook for Midwives.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
