    unit,
    topic
) VALUES (
    'The part of foetal presentation used to describe the position is referred to as:-',
    'Attitude',
    'Lie',
    'Fetal axis',
    'Denominator',
    'D',
    'The denominator is the named part of the presentation used to describe fetal position (e.g. occiput for vertex, sacrum for breech, mentum for face). Attitude is the relation of fetal parts to each other, and lie is the relation of the fetal to maternal long axis. Per Myles Textbook for Midwives.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Midwifery',
    'General Midwifery'
) ON CONFLICT (stem, cadre) DO NOTHING;

