    unit,
    topic
) VALUES (
    'The correct regimen for administering magnesium Sulphate loading dose intramuscularly is:-',
    '5 g given as a divided dose in each of the buttocks over a period of 10-15 minutes',
    '10 g as a divided dose in each of the buttock',
    '4g as divided dose in each buttock over a period of not less than 5 minutes',
    '10 g as a divided dose in each of the buttock over a period 4 hourly',
    'A',
    'The Pritchard IM loading regimen for magnesium sulphate gives 10 g total IM as 5 g deep into each buttock (with 4 g IV loading). Among the options, 5 g in each buttock correctly reflects the divided IM loading dose. Per Kenya EmONC/pre-eclampsia-eclampsia guidelines.',
    'KRCHN',
    'Paper I',
    2026,
