    exam_year,
    status,
    difficulty,
    unit,
    topic
) VALUES (
    'In management of uterine inversion:-',
    'Oxytocin is administered before the correction of the inversion to control bleeding.',
    'Antibiotics are administered during the correction of the uterine inversion.',
    'Oxytocin is administered after the inversion of the uterus is corrected.',
    'Intravenous fluids are not necessary during the management of uterine inversion.',
    'C',
    'In uterine inversion, oxytocics are WITHHELD until the uterus is repositioned, because giving them before correction contracts the uterus around the inversion and prevents replacement. Once the fundus is restored, oxytocin is given to maintain contraction and control haemorrhage. IV fluids/resuscitation are essential (Myles Textbook for Midwives; Kenya EmONC).',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Midwifery',
    'General Midwifery'
) ON CONFLICT (stem, cadre) DO NOTHING;

