    exam_year,
    status,
    difficulty,
    unit,
    topic
) VALUES (
    'Factors that determine safety of the second stage of labour, that must be carefully monitored include:-',
    'Fetal and maternal conditions, descent of the presenting part, asepsis.',
    'Uterine contractions, fetal and maternal conditions, descent of the presenting part.',
    'Uterine contractions, state of the membranes, descent of the presenting part.',
    'Fetal and maternal conditions, asepsis, state of membranes.',
    'B',
    'Safe conduct of the second stage requires monitoring uterine contractions (strength/frequency), fetal condition (FHR) and maternal condition (vitals, effort), and progressive descent of the presenting part. These are the core safety parameters; asepsis is important but the best-fitting option combining the key dynamic monitoring parameters is B (Myles; Kenya EmONC partograph principles).',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Midwifery',
    'General Midwifery'
) ON CONFLICT (stem, cadre) DO NOTHING;

