    exam_year,
    status,
    difficulty,
    unit,
    topic
) VALUES (
    'A nurse intervention after membranes ruptures with cord pulsating and prolapsed out of vagina is:-',
    'Leave the cord hanging from origin',
    'Position on knee chest position',
    'Cover cord with a green towel',
    'Avoid tocolytics if available',
    'B',
    'Cord prolapse is an emergency; the mother is placed in knee-chest (or exaggerated Sims/Trendelenburg) position to relieve pressure of the presenting part on the cord. The cord is not handled or left exposed to cold, and tocolytics may be USED to reduce contractions, so ''avoid tocolytics'' is wrong. Knee-chest positioning is the correct nursing intervention (Kenya EmONC; Myles).',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Medical-Surgical Nursing',
    'General Medical-Surgical'
) ON CONFLICT (stem, cadre) DO NOTHING;

