    exam_year,
    status,
    difficulty,
    unit,
    topic
) VALUES (
    'A Rh negative women has increase the chances of being immunized during pregnancy when:-',
    'Performing External cephalic version.',
    'Maternal anemia.',
    'Premature labor.',
    'Maternal Thyrotoxicosis.',
    'A',
    'Rh isoimmunisation occurs when fetomaternal haemorrhage exposes an Rh-negative mother to Rh-positive fetal cells. External cephalic version manipulates the uterus and can cause fetomaternal transfusion, increasing sensitisation risk (an indication for anti-D). Anaemia, preterm labour and thyrotoxicosis do not directly cause isoimmunisation (Myles; Kenya ANC guidelines).',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Midwifery',
    'General Midwifery'
) ON CONFLICT (stem, cadre) DO NOTHING;

