    exam_year,
    status,
    difficulty,
    unit,
    topic
) VALUES (
    'Foetal hypoxia in first stage of labour is promptly identified by:-',
    'Observing foetal heart rate quarter (1/4) hourly, check for moulding',
    'Observing foetal heart rate half (1/2 ) hourly, check for meconium',
    'Observing foetal heart rate half (1/2) hourly, check for moulding',
    'Observing foetal heart rate quarter (1/4) hourly, check for meconium',
    'D',
    'Fetal hypoxia is detected by monitoring the FHR every 30 minutes in early first stage and every 15 minutes (quarter-hourly) in active/late first stage, together with observing for meconium-stained liquor (a sign of hypoxia). Moulding indicates obstruction/CPD, not directly hypoxia; the hypoxia indicators are frequent FHR and meconium (Kenya partograph/EmONC; Myles).',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Midwifery',
    'General Midwifery'
) ON CONFLICT (stem, cadre) DO NOTHING;

