    status,
    difficulty,
    unit,
    topic
) VALUES (
    'A major side effect of oxytocin is:-',
    'Sodium and water retention',
    'Peripheral neuropathy',
    'Hypertension',
    'Nephrotoxicity',
    'A',
    'Oxytocin has structural similarity to ADH (vasopressin) and has an antidiuretic effect, causing water and sodium retention that can lead to water intoxication/hyponatraemia, especially with prolonged high-dose infusion in electrolyte-free fluids. It does not typically cause peripheral neuropathy or nephrotoxicity (Kenya pharmacology guidelines; Brunner & Suddarth).',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Community Health Nursing',
    'General Community'
) ON CONFLICT (stem, cadre) DO NOTHING;

