    'Principles of management of a woman with postpartum haemorrhage are:-',
    'Rub up a contraction, give an oxytocic, resuscitate the mother',
    'Call a doctor, stop the bleeding, resuscitate the mother',
    'Give an oxytocic, call a doctor, stop bleeding',
    'Deliver the placenta immediately, rub a contraction, give an oxytocic',
    'A',
    'Per Kenya EmONC/Myles, the immediate management of PPH follows: rub up a contraction (stimulate the uterus to contract), administer an oxytocic to sustain contraction, and resuscitate the mother. This addresses the commonest cause (atonic uterus) first while restoring circulation.',
    'KRCHN',
    'Paper I',
