    'D',
    'High-risk pregnancies require intensified fetal surveillance; the biophysical profile (combining ultrasound assessment of movement, tone, breathing, amniotic fluid and a non-stress test) is the comprehensive antenatal tool used to assess fetal wellbeing, per Kenya ANC/EmONC guidelines and Myles. Six-weekly follow-up is inadequate and the kick chart is only a basic screen.',
    'KRCHN',
