    'Cardiac message, maintenance of patent airway, warmth and stimulation',
    'Warmth and stimulation, oxygen administration, cardiac message',
    'B',
    'Neonatal resuscitation per Kenya Basic Paediatric Protocols/HBB follows the sequence: provide warmth and stimulation (dry, stimulate), maintain a patent airway (position and clear/ventilate), and only then chest compressions (cardiac massage) if the heart rate remains low. Circulation support comes last after airway and breathing.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
