    'A 29 year old primigravida woman at 16 weeks of gestation reports irritability, palpitation and difficulty in gaining weight. Physical examination is normal except for a pulse of 104 beats/min and lid lag. Laboratory studies reveal Hb of 10.1g/dl, serum free thyroxin of 10 ng/dl and thyrotropin of 0.1 mU1ow. What is the most likely diagnosis?',
    'Thyroid storm.',
    'Hypothyroidism.',
    'Depression.',
    'Hyperthyroidism.',
    'D',
    'Irritability, palpitations, tachycardia (104 bpm), lid lag and difficulty gaining weight with a raised free thyroxine and suppressed thyrotropin (TSH 0.1) are diagnostic of hyperthyroidism. It is not a thyroid storm as there is no hyperpyrexia or crisis. Reference: Brunner & Suddarth; Kenya maternal medicine guidelines.',
    'KRCHN',
