    exam_year,
    status,
    difficulty,
    unit,
    topic
) VALUES (
    'Features of true labor include:-',
    'Regular uterine contractions, Cervix dilatation, intensity remains the same',
    'Intensity increases, bulging of membranes, contractions irregular',
    'Bulging membranes, dilatation and effacement present, pain well relieved',
    'Bulging membranes, descent of presenting part progressive, regular contractions',
    'A',
    'True labour is characterised by regular, progressively strengthening uterine contractions accompanied by cervical effacement and dilatation. Although true contractions actually increase in intensity, this is the only option combining regular contractions with cervical dilatation (the defining feature); the other options describe false labour features such as irregular contractions and pain relieved by rest.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Midwifery',
    'General Midwifery'
) ON CONFLICT (stem, cadre) DO NOTHING;

