) VALUES (
    'Physiological changes in the reproductive system include:-',
    'There is no changes in the vagina',
    'The uterus first enlarge by hyperplasia then by hypertrophy',
    'There is no change in the cervix',
    'Estrogen has no role in any changes during pregnancy',
    'B',
    'Uterine growth in pregnancy occurs initially by hyperplasia (increase in cell number) under oestrogen influence in early pregnancy, then predominantly by hypertrophy (enlargement of existing myometrial cells) as pregnancy advances. The vagina and cervix also undergo marked changes and oestrogen is central, making the other options false.',
    'KRCHN',
    'Paper I',
    2026,
