    'A',
    'Progesterone-only pills (POPs) work mainly by thickening cervical mucus and thinning the endometrium; ovulation is inhibited only inconsistently (in about 40-60% of cycles). They carry no significant DVT risk (unlike combined pills), are slightly less effective than the combined pill, and breakthrough/irregular bleeding is common, not rare. Kenya National Family Planning Guidelines; WHO MEC.',
