    'C',
    'Fetal axis pressure is the force of the fundal contraction transmitted from the upper pole down the long axis of the fetus, so the presenting part is applied to the cervix, aiding dilatation. General fluid pressure acts via the forewaters; fundal dominance describes the wave pattern. Myles Textbook for Midwives.',
    'KRCHN',
