    'D',
    'A convulsion in the third trimester indicates eclampsia; the immediate priority is patient safety—protecting her from injury and maintaining a patent airway during the fit. Magnesium sulphate (not diazepam) is the anticonvulsant of choice, given after the airway/safety are secured. Kenya EmONC/Maternal guidelines.',
