    unit,
    topic
) VALUES (
    'A patient sustained a laceration of the premium during delivery, it involved the muscles of Perineal body but not the anal sphincter. Such a laceration would be classified as :-',
    'First degree',
    'Second degree',
    'Third degree',
    'Forth degree',
    'B',
    'A second-degree perineal tear involves the perineal skin, vaginal mucosa and the muscles of the perineal body but does not reach the anal sphincter. Third degree involves the anal sphincter and fourth degree extends into the rectal mucosa. Myles Textbook for Midwives; Kenya EmONC.',
    'KRCHN',
