    exam_year,
    status,
    difficulty,
    unit,
    topic
) VALUES (
    'Acute uterine inversion following childbirth may be managed by:-',
    'Giving the woman a bolus of 20 mls of 50% dextrose 2 hourly for eight hours',
    'Attempting to restore the uterus along the direction of the vagina towards the posterior fornix',
    'Removing the placenta from uterine wall if still adherent then restoring the uterus by hydrostatic pressure',
    'Giving intramyometrial syntocinon then removing the placenta if still attached to the uterus',
    'C',
    'In acute uterine inversion, the classic management includes replacement of the uterus; where the placenta is still adherent it should not be removed before replacement in the immediate manual approach, but the hydrostatic (O''Sullivan) method involves reduction using warm-saline hydrostatic pressure. Among the options, C best describes an accepted approach (removal of adherent placenta then hydrostatic replacement). Reference: Myles Textbook for Midwives; Kenya EmONC guidelines.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Midwifery',
    'General Midwifery'
) ON CONFLICT (stem, cadre) DO NOTHING;

