) VALUES (
    'Sickle cell: -',
    'Diseases presents in a heterotype (SA).',
    'Increases the risk of urinary tract infections.',
    'Iron binding capacity',
    'Should be always given iron to avoid anemia.',
    'B',
    'Sickle cell disease impairs renal medullary concentrating ability and predisposes to urinary stasis and infection, increasing UTI risk (especially in pregnancy). Heterozygous state is sickle cell trait not disease, iron is contraindicated unless deficient, so those options are wrong. Reference: Brunner & Suddarth; Kenya haematology guidelines.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
