) VALUES (
    'Bacterial Vaginosis: -',
    'Is rare vaginal infection.',
    'Is always symptomatic.',
    'Is usually associated with profound inflammatory reaction.',
    'Causes fishy discharge which results from bacterial amine production.',
    'D',
    'Bacterial vaginosis produces a thin greyish-white discharge with a fishy odour from amines (putrescine, cadaverine) released by anaerobic bacteria, positive on whiff test. It is common, often asymptomatic, and characteristically lacks inflammation (hence ''vaginosis'' not ''vaginitis''). Reference: Kenya STI guidelines; Brunner & Suddarth.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Medical-Surgical Nursing',
    'General Medical-Surgical'
) ON CONFLICT (stem, cadre) DO NOTHING;

