    'Enlargement of the pelvic cavity.',
    'D',
    'Under the influence of relaxin and progesterone the pelvic ligaments and symphysis pubis soften and relax at term, permitting slight increase in joint mobility and effective enlargement of the pelvic cavity to aid delivery. Reference: Myles Textbook for Midwives.',
    'KRCHN',
