) VALUES (
    'A bishop’s score of 4 indicates that:-',
    'Labour is progressing well and augmentation yields good results.',
    'There is poor prognosis therefore do not augment.',
    'Amniotomy can be done with or without oxytocics.',
    'There is possibility of good prognosis therefore augment.',
    'D',
    'A Bishop score of 4 (favourable trend, generally a score above 3-5 considered increasingly favourable) suggests a reasonable prognosis for successful induction/augmentation. Of the options, D best fits that a score of 4 indicates possibility of good prognosis warranting augmentation. Reference: Myles Textbook for Midwives; Kenya labour management guidelines.',
    'KRCHN',
