) VALUES (
    'A higher blood volume is required in pregnancy to:-',
    'Maintain normal vascular peripheral resistance',
    'Increase flow to the liver for adequate metabolism',
    'Counter balance effects of lowered osmotic pressure and immunity',
    'Counter balance the effects of increased arterial and venous capacity',
    'D',
    'Blood volume rises about 40-50% in pregnancy to fill the expanded vascular bed (increased arterial and venous capacity from vasodilatation and the added uteroplacental circulation) and to safeguard against blood loss at delivery. Reference: Myles Textbook for Midwives.',
    'KRCHN',
