    correct_option,
    rationale,
    cadre,
    paper,
    exam_year,
    status,
    difficulty,
    unit,
    topic
) VALUES (
    'You are asked to see a 21-year-old woman for preconception care. She was diagnosed with generalised tonic-clonic epilepsy four years ago. This is poorly controlled. She is currently on sodium valproate and levetiracetam. What is the next step in her management?',
    'Arrange MRI',
    'Review medication',
    'Commence aspirin 75 mg',
    'Commence folic acid 5 mg',
    'B',
    'Sodium valproate is highly teratogenic (neural tube and other defects, neurodevelopmental harm) and must be avoided in women of childbearing potential; with poorly controlled epilepsy the priority preconception step is to review/switch antiepileptic medication to a safer agent under specialist care before pregnancy. High-dose folic acid 5 mg is also needed but medication review is the essential next step given valproate. Reference: Kenya/NCK pharmacology and preconception guidelines.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'easy',
    'Midwifery',
    'General Midwifery'
) ON CONFLICT (stem, cadre) DO NOTHING;

INSERT INTO questions (
    stem,
