    exam_year,
    status,
    difficulty,
    unit,
    topic
) VALUES (
    'Pawlick’s maneuver:-',
    'Usually done during lateral palpation of the abdomen',
    'Helps diagnose the lie of the fetus in the uterus',
    'Helps determine the size, flexion and motility of the fetal head',
    'Use in the second stage of labour ward to determine the position of the membranes.',
    'C',
    'Pawlik''s manoeuvre is a deep pelvic grip in which the midwife grasps the lower pole of the uterus between thumb and fingers over the symphysis pubis to assess the presenting part (usually the head), determining its size, degree of flexion and mobility/engagement. It is not the lateral grip and does not diagnose lie. Reference: Myles Textbook for Midwives; NCK antenatal abdominal examination.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Midwifery',
    'General Midwifery'
) ON CONFLICT (stem, cadre) DO NOTHING;

INSERT INTO questions (
    stem,
    option_a,
    option_b,
