    cadre,
    paper,
    exam_year,
    status,
    difficulty,
    unit,
    topic
) VALUES (
    'During the 2nd stage of labor, external rotation of the fetal head assists the midwife to realize that: -',
    'Foetal shoulders have descended',
    'Foetal body is in the lateral position',
    'Foetal shoulders have rotated into anterior-posterior of the outlet',
    'Occiput has slipped under the sub-pubic',
    'A',
    'After the head delivers and restitutes, external rotation follows because the shoulders rotate to bring the bisacromial diameter into the antero-posterior of the outlet as they descend; the visible external rotation of the head therefore signals that the shoulders have descended and rotated internally. This alerts the midwife to prepare for delivery of the shoulders. Reference: Myles Textbook for Midwives, mechanism of normal labour.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Midwifery',
    'General Midwifery'
) ON CONFLICT (stem, cadre) DO NOTHING;

