    unit,
    topic
) VALUES (
    'The prophylactic measures PMTCT among HIV positive mothers is:-',
    'AZT should be started as early as 14 weeks gestation',
    'TDF + 3TC + DTG',
    'AZT +3TC + DTG for 6 weeks',
    'Single dose NVP should be given for 7 days post-partum',
    'B',
    'Current Kenya MOH/ARV PMTCT guidelines recommend lifelong triple ART (Option B+) for all HIV-positive pregnant women, with the first-line regimen being TDF + 3TC + DTG started immediately regardless of gestation or CD4. Single-dose NVP and short AZT-only courses are outdated. Reference: Kenya ARV Guidelines / PMTCT.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Pharmacology',
    'General Pharmacology'
) ON CONFLICT (stem, cadre) DO NOTHING;

