    status,
    difficulty,
    unit,
    topic
) VALUES (
    'The maternal surface of the placenta contains: -',
    'Chorion and visible blood vessels',
    'Cotyledons and amnion',
    'Blood vessel and amnion',
    'Cotyledons and chorion',
    'D',
    'The maternal (uterine) surface of the placenta is dark red, rough and divided into 15-20 lobes called cotyledons, and is covered by a thin layer of the chorion (basal decidua/chorionic tissue). The fetal surface is the smooth, shiny one covered by amnion with visible vessels. Reference: Myles Textbook for Midwives, placenta at term.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Midwifery',
