    status,
    difficulty,
    unit,
    topic
) VALUES (
    'The best time to infiltrate the perineum with lignocaine is:-',
    'Before performing an episiotomy',
    'After performing an episiotomy',
    'After delivery of the baby',
    'Before suturing an episiotomy',
    'A',
    'Lignocaine should be infiltrated into the perineum before performing an episiotomy so that the incision is made while the tissue is anaesthetised, providing pain relief for the cut and later repair. Infiltrating after the cut defeats the analgesic purpose. Reference: Kenya EmONC / Myles Textbook for Midwives, episiotomy procedure.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Surgical Nursing',
