    'Have a sliding lock in the order to correct asynclitism',
    'D',
    'Kjelland''s forceps have a sliding lock which allows correction of asynclitism, minimal pelvic curve, and are used for rotational (e.g. occipito-posterior/transverse) deliveries with the head engaged. The knobs on the shank point toward the occiput, not sinciput. Reference: Myles Textbook for Midwives, instrumental delivery.',
    'KRCHN',
