    'Breast abscess.',
    'C',
    'Puerperal mastitis is the most common complication associated with breastfeeding, arising from milk stasis and cracked nipples allowing bacterial entry; if untreated it may progress to a breast abscess (a less common sequel). Reference: Myles Textbook for Midwives; Kenya postnatal care guidelines.',
