    difficulty,
    unit,
    topic
) VALUES (
    'Foetal complications resulting from obstructed labour include:-',
    'Meconium aspiration, chorioamnionitis',
    'Intra- uterine hypoxia, neonatal jaundice',
    'Neonatal jaundice, meconium aspiration',
    'Intrauterine hypoxia, ascending infection',
    'D',
    'Obstructed labour causes fetal intra-uterine hypoxia/asphyxia from impaired placental perfusion and, with prolonged rupture of membranes, ascending intra-uterine infection (chorioamnionitis/sepsis). These are the direct fetal complications. Reference: Kenya EmONC; Myles Textbook for Midwives.',
    'KRCHN',
