    'Inner cell mass.',
    'Trophoblast.',
    'Human Chorionic gonadotrophin.',
    'Amniotic fluid',
    'B',
    'The chorion develops from the trophoblast (outer cell layer of the blastocyst) together with extra-embryonic mesoderm, forming the outer fetal membrane and later the fetal part of the placenta. The inner cell mass forms the embryo and amnion. Reference: Myles Textbook for Midwives, embryology.',
    'KRCHN',
