    status,
    difficulty,
    unit,
    topic
) VALUES (
    'Kangaroo technique to ensure warmth to a low-birth-weight baby involves:-',
    'Dry the baby properly and wrap with warm clothes, covering head with hat',
    'Room temperature of 21-24 0 C and baby dressed in warm clothing',
    'Baby placed inside the blouse to allow skin to skin contact and baby breastfed freely',
    'Mother sleeps in semi-sitting position and covers herself well to keep the baby warm',
    'C',
    'Kangaroo Mother Care (KMC) is defined by continuous skin-to-skin contact between the mother''s chest and the naked baby, held inside the mother''s clothing, together with exclusive/frequent breastfeeding. This maintains the LBW baby''s warmth and promotes bonding per Kenya Basic Newborn/KMC guidelines and Myles. The other options describe general thermal care but not the defining KMC technique.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Medical-Surgical Nursing',
    'General Medical-Surgical'
) ON CONFLICT (stem, cadre) DO NOTHING;

