    exam_year,
    status,
    difficulty,
    unit,
    topic
) VALUES (
    'The volume of amniotic fluid is:-',
    'Maybe predicted by ultrasound',
    'Is reduced in sever rhesus disease',
    'Increases following amniocentesis',
    'Is closely related to the fetal crown-rump length in the 3rd trimester of pregnancy',
    'A',
    'Amniotic fluid volume can be estimated/predicted by ultrasound (amniotic fluid index / deepest pool). It is INCREASED (not reduced) in severe rhesus disease due to fetal hydrops/polyuria, is not increased by amniocentesis, and is not closely related to crown-rump length (a first-trimester measure). Per Myles Textbook for Midwives, ultrasound assessment is the correct statement.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Midwifery',
    'General Midwifery'
) ON CONFLICT (stem, cadre) DO NOTHING;

