    exam_year,
    status,
    difficulty,
    unit,
    topic
) VALUES (
    'Woods’ manoeuvre is applied when:-',
    'Exert pressure on the posterior shoulder to bring posterior shoulder forward',
    'Baby head is returned into vagina and taken in for caesarian section',
    'Pressure applied at the back of fetal shoulder towards the fetal chest just above the symphsis pubis.',
    'Assisting the mother onto her hands and knees',
    'A',
    'Woods'' (corkscrew) manoeuvre for shoulder dystocia involves inserting a hand vaginally and applying pressure on the anterior aspect of the posterior shoulder to rotate it, bringing the posterior shoulder forward around the pelvis to disimpact the anterior shoulder. Option C describes suprapubic pressure, and D describes the all-fours (Gaskin) manoeuvre. Per Myles/EmONC guidelines this rotational internal manoeuvre is Woods''.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Midwifery',
