    cadre,
    paper,
    exam_year,
    status,
    difficulty,
    unit,
    topic
) VALUES (
    'Upon examination of a pregnant woman at 20 weeks’ gestation, the nurse notes that the vaginal and cervix is deep reddish purple color. The nurse would record this as:-',
    'Hegars sign',
    'Goodels sign',
    'Chadwicks sign',
    'Hyperpigmentation of the genitalia',
    'C',
    'Chadwick''s sign is the bluish/deep reddish-purple (violet) discolouration of the vagina and cervix due to increased vascularity in pregnancy. Hegar''s sign is softening of the lower uterine segment/isthmus, and Goodell''s sign is softening of the cervix. This is a classic probable sign of pregnancy per Kozier/Myles.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Midwifery',
    'General Midwifery'
) ON CONFLICT (stem, cadre) DO NOTHING;

