    paper,
    exam_year,
    status,
    difficulty,
    unit,
    topic
) VALUES (
    'In Schultz mechanism during third stage of labour:-',
    'The placenta begins to separate from one of the lateral borders',
    'Blood from placental site escapes so that separation is unaided by a retro placental clot',
    'The placenta descends, slipping sideways, maternal surface first at the vulva',
    'Placenta begins to separate centrally and a retro placental clot is formed aiding the separation',
    'D',
    'In the Schultze mechanism of placental separation, the placenta separates centrally first, a retroplacental clot forms behind it aiding separation, and it descends fetal (shiny) surface first. Options describing lateral separation and maternal surface presenting first describe the Matthews Duncan mechanism. Per Myles Textbook for Midwives.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Midwifery',
    'General Midwifery'
) ON CONFLICT (stem, cadre) DO NOTHING;

