    cadre,
    paper,
    exam_year,
    status,
    difficulty,
    unit,
    topic
) VALUES (
    'Major factor for the fetal RBC to cross to the mother:-',
    'Labor and delivery',
    'Spontaneous abortion',
    'Low Abruption placenta',
    'Placenta praevia',
    'A',
    'The major cause of fetomaternal haemorrhage (fetal RBCs crossing into maternal circulation, causing Rh sensitisation) is labour and delivery, when placental separation allows the greatest transfer of fetal cells. While abortion, abruption and other events can cause some transfer, delivery is the principal/major sensitising event. Per Myles and Kenya EmONC/Rh prophylaxis guidance.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
