    'Engagement of fetus',
    'C',
    'Lateral palpation of the abdomen locates the fetal back and limbs on either side of the maternal abdomen, thereby determining the position (and lie) of the fetus. Fundal height/fundal palpation assesses the pole in the fundus, pelvic palpation assesses presentation and engagement. Per Myles antenatal abdominal examination technique.',
