) VALUES (
    'A client with pneumonia has a temperature of 39.5°C, pulse 120/min, respirations 32/min, and BP 110/70 mmHg. The vital sign change that is most directly related to hypoxemia is;',
    'Elevated body temperature from infection process',
    'Increased respiratory rate from impaired gas exchange',
    'Stable blood pressure despite systemic inflammation',
    'Mild tachycardia resulting from elevated temperature',
    'B',
    'Hypoxaemia stimulates chemoreceptors producing tachypnoea; the raised respiratory rate (32/min) reflects impaired gas exchange in pneumonia and is the sign most directly related to hypoxaemia (Brunner & Suddarth). Fever and tachycardia relate to infection/temperature rather than directly to hypoxaemia.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Medical-Surgical Nursing',
    'General Medical-Surgical'
) ON CONFLICT (stem, cadre) DO NOTHING;

