    status,
    difficulty,
    unit,
    topic
) VALUES (
    'Factors that can lead to myocardial ischemia include;',
    'Anemia, aortic valve stenosis, polycythemia',
    'Mitral valve stenosis, anemia, left ventricular hypertrophy',
    'Anemia, aortic valve stenosis, mitral valve stenosis',
    'Polycythemia, mitral valve stenosis, left ventricular hypertrophy',
    'A',
    'Myocardial ischemia results from imbalance between oxygen supply and demand. Anemia reduces oxygen-carrying capacity, aortic stenosis increases myocardial workload/demand and reduces coronary perfusion, and polycythemia increases blood viscosity impairing coronary flow. All three provoke ischemia per Brunner & Suddarth cardiovascular pathophysiology.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Anatomy & Physiology',
    'General Anatomy'
) ON CONFLICT (stem, cadre) DO NOTHING;

