    unit,
    topic
) VALUES (
    'The condition in which the eyes balls are not properly aligned with each other is referred to as: -',
    'Astigmatism',
    'Strabismus',
    'Presbyopia',
    'Amblyopia',
    'B',
    'Strabismus is the misalignment of the eyes (squint) where the eyeballs are not properly aligned with each other. Astigmatism is a refractive error, presbyopia is age-related loss of accommodation, and amblyopia is ''lazy eye'' with reduced vision. Standard ophthalmology/Brunner definition.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Medical-Surgical Nursing',
    'General Medical-Surgical'
) ON CONFLICT (stem, cadre) DO NOTHING;

