    exam_year,
    status,
    difficulty,
    unit,
    topic
) VALUES (
    'A client diagnosed with left-sided heart failure is most likely to exhibit:',
    'Pulmonary crackles and exertional dyspnea symptoms',
    'Bilateral calf pain and intermittent claudication',
    'Ascites and hepatomegaly from venous congestion',
    'Peripheral edema and jugular vein distension',
    'A',
    'Left-sided heart failure causes pulmonary venous congestion, producing pulmonary crackles, exertional dyspnea, orthopnea and cough. Peripheral edema, JVD, ascites and hepatomegaly are features of right-sided failure. This left-versus-right distinction is standard in Brunner & Suddarth.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Medical-Surgical Nursing',
    'General Medical-Surgical'
) ON CONFLICT (stem, cadre) DO NOTHING;

