    status,
    difficulty,
    unit,
    topic
) VALUES (
    'A client arrives with suspected tension pneumothorax. The following assessment finding requires immediate intervention to the patient;',
    'Productive cough with yellow sputum production',
    'Diminished breath sounds on one side only',
    'Mild chest discomfort during inspiration episodes',
    'Respiratory rate of twenty-two breaths per minute',
    'B',
    'In tension pneumothorax, unilaterally diminished/absent breath sounds indicate lung collapse and rising intrathoracic pressure requiring immediate needle decompression. The other findings (productive cough, mild discomfort, RR 22) are non-emergent. Recognizing absent unilateral breath sounds as the critical sign is per Brunner & Suddarth emergency care.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Medical-Surgical Nursing',
    'General Medical-Surgical'
) ON CONFLICT (stem, cadre) DO NOTHING;

