    status,
    difficulty,
    unit,
    topic
) VALUES (
    'A patient experiencing status epilepticus has been seizing continuously for 10 minutes. The medication that the nurse will administer first is;',
    'Oral phenytoin',
    'Oral carbamazepine',
    'Intravenous lorazepam',
    'Intramuscular vitamin K',
    'C',
    'Status epilepticus is first managed with a benzodiazepine; IV lorazepam is the first-line agent to abort ongoing seizure activity. Phenytoin and carbamazepine are not first-line abortive drugs (phenytoin is a second-line loading agent), and vitamin K is irrelevant. Per Kenya clinical guidelines and Brunner & Suddarth neurology.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Pharmacology',
    'General Pharmacology'
) ON CONFLICT (stem, cadre) DO NOTHING;

