    unit,
    topic
) VALUES (
    'The laboratory finding that is most consistent with iron-deficiency anemia is;',
    'Elevated hemoglobin and increased ferritin levels',
    'High reticulocyte count with polycythemia',
    'Reduced hemoglobin and low serum ferritin',
    'Increased hematocrit and elevated platelets',
    'C',
    'Iron-deficiency anaemia is characterised by low haemoglobin with low serum ferritin (depleted iron stores), a microcytic hypochromic picture. Elevated Hb, polycythaemia and raised haematocrit/platelets contradict iron deficiency. Per Brunner & Suddarth and Kenya haematology guidelines.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Medical-Surgical Nursing',
    'General Medical-Surgical'
) ON CONFLICT (stem, cadre) DO NOTHING;

