    'Supporting the scrub nurse',
    'D',
    'The circulating (unscrubbed) nurse works outside the sterile field, supporting the scrub nurse and surgical team by supplying instruments, positioning, documentation and coordinating the theatre. Intubation/extubation are anaesthetist roles. Per Kozier fundamentals and perioperative nursing standards.',
    'KRCHN',
