) VALUES (
    'In addition to the general symptoms of anaemia, a patient with pernicious anaemia also manifest with: -',
    'Coagulation deficiencies',
    'Low immunity',
    'Neurological symptoms',
    'Cardiovascular disturbances',
    'C',
    'Pernicious anaemia results from vitamin B12 deficiency, which is essential for myelin; deficiency causes neurological manifestations such as paraesthesia, ataxia and impaired proprioception (subacute combined degeneration) in addition to general anaemia symptoms. Brunner & Suddarth.',
    'KRCHN',
