) VALUES (
    'A client with infective endocarditis is receiving intravenous antibiotics. An essential nursing intervention would be to;',
    'Monitor temperature trends and blood cultures',
    'Restrict fluid intake below one liter daily',
    'Encourage strenuous exercise to improve strength',
    'Maintain complete bed rest throughout therapy',
    'A',
    'In infective endocarditis on IV antibiotics, monitoring temperature trends and serial blood cultures assesses response to therapy and clearance of the infection, guiding treatment. Fluid restriction, strenuous exercise and mandatory complete bed rest are not indicated. Brunner & Suddarth.',
    'KRCHN',
