    'Help assess functioning of the mitral and tricuspid valves',
    'B',
    'CVP reflects right atrial/right heart filling pressure and is used to guide and monitor fluid replacement therapy and right-sided cardiac function in the critically ill. Left-sided assessment requires pulmonary artery wedge pressure. Brunner & Suddarth critical care nursing.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
