    exam_year,
    status,
    difficulty,
    unit,
    topic
) VALUES (
    'A patient with heart failure develops sudden frothy pink sputum and severe dyspnea. The first  action the nurse should perform first is;',
    'Place patient in high Fowler''s position',
    'Obtain detailed dietary assessment history',
    'Encourage oral fluid intake immediately',
    'Prepare patient for discharge planning',
    'A',
    'Frothy pink sputum with severe dyspnea signals acute pulmonary oedema. The immediate priority is positioning the patient upright (high Fowler''s) to reduce venous return and improve ventilation while oxygen and drugs are prepared (Brunner & Suddarth; Kenya MOH). Fluids and dietary history are inappropriate.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Pharmacology',
