    exam_year,
    status,
    difficulty,
    unit,
    topic
) VALUES (
    'A patient with hypertension is prescribed enalapril. Which adverse effect should the nurse monitor the patient for;',
    'Severe constipation and urinary retention',
    'Persistent dry cough and hypotension',
    'Bradycardia and excessive salivation episodes',
    'Visual disturbances and hearing impairment',
    'B',
    'Enalapril is an ACE inhibitor; the classic adverse effects are a persistent dry cough (from bradykinin accumulation) and hypotension (first-dose and dose-related). Hyperkalaemia and angioedema also occur (Kenya Pharmacology guidelines; BNF).',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Pharmacology',
    'General Pharmacology'
) ON CONFLICT (stem, cadre) DO NOTHING;

