    status,
    difficulty,
    unit,
    topic
) VALUES (
    'Post below below-knee amputation in a patient with diabetes poses the risk of:-',
    'Hemorrhage',
    'Edema of the stump',
    'Contractures',
    'Wound dehiscence',
    'A',
    'In a diabetic patient (peripheral vascular disease, fragile vessels), the immediate post-operative complication following below-knee amputation is haemorrhage from the stump, which is why a tourniquet is kept at the bedside. Brunner & Suddarth lists haemorrhage as the priority early post-op risk requiring the nurse to monitor the dressing and have haemostatic measures ready. Contractures are a later rehabilitation concern, not the acute post-op risk implied by ''post-amputation.''',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Surgical Nursing',
    'General Surgical'
) ON CONFLICT (stem, cadre) DO NOTHING;

