    status,
    difficulty,
    unit,
    topic
) VALUES (
    'Addison’s disease results form: -',
    'Decreased production of parathyroid hormone.',
    'Excessive secretion of epinephrine and norepinephrine',
    'Inadequate secretion of glucocorticoids',
    'Over activity of parathyroid glands',
    'C',
    'Addison''s disease is primary adrenocortical insufficiency, characterised by inadequate secretion of glucocorticoids (cortisol) and mineralocorticoids (aldosterone). This causes hypotension, hyperpigmentation and electrolyte disturbance (Brunner & Suddarth).',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Medical-Surgical Nursing',
    'General Medical-Surgical'
) ON CONFLICT (stem, cadre) DO NOTHING;

