    status,
    difficulty,
    unit,
    topic
) VALUES (
    'An assessment finding that is most indicative of cardiogenic shock is;',
    'Warm skin and bounding peripheral pulses',
    'Hypertension and bradycardia after exertion',
    'Hypotension with cool clammy extremities',
    'Elevated temperature with flushed appearance',
    'C',
    'Cardiogenic shock produces reduced cardiac output leading to hypotension with cool, clammy, poorly perfused extremities, tachycardia and oliguria. Warm skin/bounding pulses suggest distributive (septic) shock (Brunner & Suddarth; Kenya emergency care).',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Medical-Surgical Nursing',
    'General Medical-Surgical'
) ON CONFLICT (stem, cadre) DO NOTHING;

