    exam_year,
    status,
    difficulty,
    unit,
    topic
) VALUES (
    'A patient with common bile duct obstruction related to cancer pancreas is likely to present with: -',
    'Brown faeces, dark coloured urine',
    'Scleral icterus, malena stool',
    'Dark coloured urine, scleral icterus',
    'Jaundice, brown faeces',
    'C',
    'Obstruction of the common bile duct (e.g. by carcinoma of the head of pancreas) causes obstructive/post-hepatic jaundice: conjugated bilirubin cannot reach the gut, so it spills into blood and urine giving dark urine and scleral icterus (jaundice), while stools become pale/clay-coloured (not brown) due to absent stercobilin. Melaena is not a feature. Per Brunner & Suddarth Medical-Surgical Nursing.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Medical-Surgical Nursing',
    'General Medical-Surgical'
) ON CONFLICT (stem, cadre) DO NOTHING;

