    exam_year,
    status,
    difficulty,
    unit,
    topic
) VALUES (
    'A patient with chronic kidney disease suddenly develops chest pain and peaked T waves. As the nurse caring for the patient, you will suspect?',
    'Hyperkalemia',
    'Hypocalcemia',
    'Hypoglycemia',
    'Hypernatremia',
    'A',
    'Chronic kidney disease impairs potassium excretion causing hyperkalaemia, whose hallmark ECG change is tall, peaked T waves; associated cardiac irritability can cause arrhythmia and chest symptoms. This is a life-threatening electrolyte emergency. Per Brunner & Suddarth Medical-Surgical Nursing.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Medical-Surgical Nursing',
    'General Medical-Surgical'
) ON CONFLICT (stem, cadre) DO NOTHING;

