    status,
    difficulty,
    unit,
    topic
) VALUES (
    'The primary rationales for tube feeding for a client post total laryngectomy due to cancer of larynx is to:-',
    'Meet dietary needs and prevent fistula formation',
    'Maintain an open airway and prevent aspiration',
    'Meet fluid & dietary needs and prevent aspiration',
    'Prevent fistula formation and reduce aspiration',
    'C',
    'After total laryngectomy the pharynx/suture line must heal; tube (nasogastric) feeding meets fluid and nutritional needs while bypassing the oral/pharyngeal route to prevent aspiration and protect the suture line during healing. The airway is separately secured by the tracheostomy stoma. Per Brunner & Suddarth Medical-Surgical Nursing.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Pharmacology',
    'General Pharmacology'
) ON CONFLICT (stem, cadre) DO NOTHING;

