    status,
    difficulty,
    unit,
    topic
) VALUES (
    'The correct management for a patient with an atrial fibrillation that has clinically manifested for 12hrs is: -',
    'Cardioversion.',
    'Defibrillation',
    'Cardioversion and defibrillation',
    'Pacing.',
    'A',
    'For symptomatic atrial fibrillation of recent onset (within about 48 hours), synchronised electrical (or pharmacological) cardioversion is used to restore sinus rhythm. Defibrillation is for pulseless VT/VF, not AF; pacing treats bradyarrhythmias. Per Brunner & Suddarth Medical-Surgical Nursing / ACLS.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Medical-Surgical Nursing',
    'General Medical-Surgical'
) ON CONFLICT (stem, cadre) DO NOTHING;

