    exam_year,
    status,
    difficulty,
    unit,
    topic
) VALUES (
    'In caring for a skin graft site, the nurse should: -',
    'Perform the first dressing change after 2 to 5 days.',
    'Nurse grafted extremity in a neutral position.',
    'Apply an occlusive dressing daily till the graft takes.',
    'Daily apply sterile saline compresses to prevent drying of the graft.',
    'A',
    'A skin graft must be left undisturbed for the first few days to allow revascularisation (imbibition then inosculation); the initial dressing is therefore typically left intact and first changed around days 3-5 to avoid dislodging the graft. The extremity is immobilised/elevated (not merely neutral), and grafts are kept moist but not allowed to dry. Per Brunner & Suddarth Medical-Surgical Nursing.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Medical-Surgical Nursing',
    'General Medical-Surgical'
) ON CONFLICT (stem, cadre) DO NOTHING;

