    status,
    difficulty,
    unit,
    topic
) VALUES (
    'Management of osteoporosis include: -',
    'Increased calcium intake, decreased coffee intake',
    'Performing weight bearing exercises, Increased calcium intake',
    'Decreased calcium intake, engaging in regular moderate activity',
    'Cessation of smoking, avoiding weight bearing exercises',
    'B',
    'Osteoporosis management centres on increasing calcium and vitamin D intake and performing regular weight-bearing exercise to stimulate bone formation and slow bone loss (Brunner & Suddarth). Both elements in this option are correct; calcium should be increased, not decreased, so options C is wrong, and weight-bearing exercise should be encouraged, so D is wrong.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Anatomy & Physiology',
    'General Anatomy'
) ON CONFLICT (stem, cadre) DO NOTHING;

