    status,
    difficulty,
    unit,
    topic
) VALUES (
    'For a patient to undergo a kidney, ureter and bladder X-ray is important for the nurse to know that: -',
    'There is no special preparation required.',
    'Oral fluids must be withheld the morning of the examination.',
    'The patient should have a full bladder before the procedure.',
    'An enema should be administered before the procedure',
    'A',
    'A plain KUB (kidney, ureter, bladder) X-ray is a simple radiograph requiring no contrast, fasting, bowel prep or bladder filling (Brunner & Suddarth diagnostic nursing). Therefore no special preparation is needed.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
