) VALUES (
    'To administer Normal saline 500mls for 6hrs using an IV administration set with a drop factor of 20, the flow rate will be regulated to:',
    '26 drops per minute',
    '25 drops per minute',
    '28 drops per minute',
    '27 drops per minute',
    'C',
    'Flow rate = (volume x drop factor)/time in minutes = (500 x 20)/(6 x 60) = 10000/360 = 27.8, which rounds to 28 drops per minute (standard IV drip calculation, Kozier). This gives the closest whole-number rate.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Pharmacology',
    'General Pharmacology'
) ON CONFLICT (stem, cadre) DO NOTHING;

