    'In Kubler-Ross''s stages of dying, depression is the stage where the patient becomes withdrawn, sad and cries as though mourning the anticipated loss (Kozier; psychosocial nursing). This matches the described behaviour better than anger or bargaining.',
    'KRCHN',
