    'Simple partial seizure',
    'D',
    'A simple partial (focal) seizure arises from a localized area of one cerebral hemisphere and may produce isolated motor activity in a single body part such as a finger or hand, without loss of consciousness. Absence and petit mal seizures are generalized, and complex partial seizures involve impaired awareness. Reference: Brunner & Suddarth Medical-Surgical Nursing.',
