    'A patient with meningitis suddenly develops seizures and decreasing consciousness. The priority nursing action by the nurse would be;',
    'Protect airway and ensure safety',
    'Administer oral medication',
    'Provide dietary education',
    'Assess bowel sounds',
    'A',
    'During a seizure with decreasing consciousness the priority follows the ABCs: maintain a patent airway, position the patient safely to prevent injury and aspiration. Oral medication is contraindicated in a seizing/unconscious patient, and dietary education or bowel assessment are not priorities. Reference: Kozier Fundamentals; Brunner & Suddarth.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
