    'B',
    'After tympanoplasty, patients must avoid increasing middle-ear pressure; blowing the nose or closed-mouth sneezing transmits pressure via the Eustachian tube and can disrupt the graft, so they are taught to sneeze with the mouth open. Reference: Brunner & Suddarth ENT post-operative care.',
