    'C',
    'After inguinal herniorrhaphy, scrotal oedema is common; elevating and supporting the scrotum (e.g., scrotal support/ice) reduces oedema and relieves pain. A truss is not used post-repair. Reference: Brunner & Suddarth surgical nursing.',
