) VALUES (
    'A patient taking chlorpromazine reports dizziness upon standing suddenly from bed. The side effect that is most likely occurring is;',
    'Orthostatic hypotension from alpha-adrenergic blockade effects',
    'Neuroleptic malignant syndrome with autonomic instability features',
    'Extrapyramidal rigidity from excessive dopamine suppression',
    'Anticholinergic crisis involving urinary retention symptoms',
    'A',
    'Chlorpromazine is a low-potency phenothiazine with strong alpha-adrenergic blocking activity, causing orthostatic (postural) hypotension manifesting as dizziness on standing suddenly. This is distinct from EPS, NMS or anticholinergic retention. Per Kenya pharmacology guidelines and Brunner & Suddarth.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Medical-Surgical Nursing',
