    difficulty,
    unit,
    topic
) VALUES (
    'A child who presents with facial edema, tea-colored urine, and hypertension following untreated sore throat infection is likely to be suffering from;',
    'Acute kidney injury caused by severe dehydration episodes',
    'Nephrotic syndrome causing excessive protein urinary losses',
    'Urinary tract infection involving ascending bacterial invasion',
    'Acute glomerulonephritis following streptococcal infection exposure',
    'D',
    'Facial/periorbital oedema, tea-coloured (haematuric) urine and hypertension after an untreated streptococcal sore throat are the classic triad of post-streptococcal acute glomerulonephritis, per Kenya Basic Paediatric Protocols and Nelson/Brunner paediatric nephrology. Nephrotic syndrome causes heavy proteinuria without haematuria, and UTI/AKI do not fit this post-strep picture.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Paediatric Nursing',
    'General Paediatric'
) ON CONFLICT (stem, cadre) DO NOTHING;

