    status,
    difficulty,
    unit,
    topic
) VALUES (
    'As the nurse in a paediatric ward, you will suspect increased intracranial pressure in a pediatric patient when you observe;',
    'Bradycardia accompanied by irregular respiratory patterns',
    'Polyuria accompanied by excessive oral fluid intake',
    'Hypotension associated with reduced peripheral circulation',
    'Tachycardia associated with elevated body temperature readings',
    'A',
    'Raised intracranial pressure produces Cushing''s response: bradycardia, irregular respirations and widening pulse pressure/hypertension, per Brunner & Suddarth and Kenya paediatric neuro guidelines. Tachycardia, hypotension and polyuria are not signs of rising ICP.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Paediatric Nursing',
    'General Paediatric'
) ON CONFLICT (stem, cadre) DO NOTHING;

