) VALUES (
    'An assessment finding that strongly suggests severe respiratory distress in an infant is;',
    'Mild cough during feeding',
    'Occasional sneezing during sleep',
    'Respiratory rate of 32 breaths/minute',
    'Head bobbing with grunting respirations',
    'D',
    'Grunting and head bobbing indicate severe respiratory distress and increased work of breathing in infants, per Kenya IMNCI/Basic Paediatric Protocols. A rate of 32/min is normal for an infant, and mild cough or occasional sneezing are not danger signs.',
    'KRCHN',
    'Paper I',
