    difficulty,
    unit,
    topic
) VALUES (
    'A 2-year-old child is admitted with an inspiratory stridor, barking cough, and hoarseness that worsens at night. The child is likely to be suffering from;',
    'Bronchial asthma causing reversible airway hyperreactivity episodes',
    'Acute bronchiolitis causing lower airway inflammation symptoms',
    'Viral croup causing upper airway obstruction manifestations',
    'Bacterial pneumonia producing alveolar consolidation changes',
    'C',
    'Inspiratory stridor, a barking (seal-like) cough and hoarseness worsening at night in a toddler are hallmark features of viral croup (laryngotracheobronchitis), an upper airway obstruction, per Kenya paediatric protocols. Asthma and bronchiolitis cause lower-airway wheeze, and pneumonia causes consolidation without barking cough/stridor.',
    'KRCHN',
    'Paper I',
