    'D',
    'A cleft palate impairs the infant''s ability to create suction, causing feeding difficulties and risk of aspiration and poor weight gain, per Kenya neonatal/paediatric and midwifery guidelines. Cyanotic cardiac episodes, renal hypertension and retinal defects are not primary cleft-palate risks.',
