    'Persistent dehydration',
    'C',
    'Per Kenya IMNCI, two of the following classify severe dehydration: lethargic/unconscious, sunken eyes, not able to drink or drinking poorly, and skin pinch going back very slowly. This child has lethargy, inability to drink, and very slow skin pinch, meeting the criteria for severe dehydration.',
