    'Pleural effusion causing mediastinal structure displacement',
    'Acute epiglottitis causing upper airway obstruction symptoms',
    'Pulmonary tuberculosis causing chronic cavitary lung lesions',
    'B',
    'Sudden reduced breath sounds with tracheal deviation in a child with pneumonia suggests accumulation of pleural fluid (parapneumonic effusion/empyema) shifting the mediastinum and trachea. Of the options, pleural effusion best fits this clinical picture. Reference: Kenya Basic Paediatric Protocols.',
    'KRCHN',
