    difficulty,
    unit,
    topic
) VALUES (
    'You the nurse caring for a child with sickle cell disease who complains of severe limb pain after a dehydrating exposure. The child is likely to be developing;',
    'Hemorrhagic crisis involving extensive blood volume loss',
    'Vaso-occlusive crisis causing tissue ischemia and pain',
    'Aplastic crisis involving temporary bone marrow suppression',
    'Hyperhemolytic crisis causing excessive red cell destruction',
    'B',
    'Dehydration precipitates sickling and vaso-occlusion, causing painful ischemia in the limbs; this is the classic vaso-occlusive (painful) crisis per Kenya paediatric/haematology guidelines. Aplastic crisis presents with anemia (parvovirus), and hyperhemolytic/hemorrhagic patterns do not fit dehydration-triggered limb pain.',
    'KRCHN',
