    'Monitoring daily weight to evaluate fluid retention changes',
    'Restricting all oral fluids regardless of hydration status',
    'Promoting vigorous physical activity to reduce edema formation',
    'B',
    'In nephrotic syndrome, daily weight is the most reliable objective measure of fluid retention and response to therapy, guiding management of oedema. Sodium is restricted (not encouraged), fluids are managed per status rather than totally withheld, and activity is modified during acute oedema. Reference: Kenya Basic Paediatric Protocols; Brunner & Suddarth.',
