) VALUES (
    'A priority nursing intervention while managing a child with of diabetic ketoacidosis is;',
    'Initiating rapid insulin therapy with fluid replacement',
    'Restricting intravenous fluids to prevent cerebral edema',
    'Encouraging high-carbohydrate meals during hyperglycemia episodes',
    'Delaying electrolyte monitoring until glucose normalizes fully',
    'A',
    'Priority management of paediatric DKA is fluid resuscitation together with insulin therapy to correct hyperglycaemia and acidosis, alongside electrolyte (especially potassium) monitoring. Fluids are not restricted, high-carbohydrate feeds are contraindicated, and electrolytes must be monitored promptly. Reference: Kenya Basic Paediatric Protocols; Brunner & Suddarth.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Paediatric Nursing',
    'General Paediatric'
) ON CONFLICT (stem, cadre) DO NOTHING;

INSERT INTO questions (
