    exam_year,
    status,
    difficulty,
    unit,
    topic
) VALUES (
    'A 10-year-old child presents to the hospital with migratory joint pain, fever, and a new cardiac murmur two weeks after untreated sore throat infection.',
    'Septic arthritis caused by hematogenous bacterial dissemination',
    'Osteomyelitis involving inflammatory destruction of bone tissue',
    'Juvenile rheumatoid arthritis causing chronic synovial inflammation',
    'Rheumatic fever following untreated streptococcal throat infection',
    'D',
    'Migratory polyarthritis, fever and new carditis (murmur) about two weeks after untreated pharyngitis are classic Jones criteria for acute rheumatic fever, a delayed autoimmune sequela of group A streptococcal throat infection. This matches Kenya Basic Paediatric Protocols and Nelson/Brunner references. Septic arthritis and osteomyelitis are localized bacterial infections without migratory arthritis or carditis.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Paediatric Nursing',
    'General Paediatric'
) ON CONFLICT (stem, cadre) DO NOTHING;

