) VALUES (
    'A congenital heart disease that is commonly associated with Down syndrome is;',
    'Patent ductus arteriosus causing persistent fetal circulation',
    'Coarctation of aorta causing obstructed systemic blood flow',
    'Atrioventricular septal defect with endocardial cushion abnormalities',
    'Tetralogy of Fallot causing cyanotic right ventricular outflow obstruction',
    'C',
    'The congenital cardiac lesion most characteristically associated with Down syndrome (trisomy 21) is the atrioventricular septal (endocardial cushion) defect. This is well established in paediatric cardiology and Nelson/Brunner texts.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Medical-Surgical Nursing',
    'General Medical-Surgical'
) ON CONFLICT (stem, cadre) DO NOTHING;

