) VALUES (
    'A finding that is characteristic of developmental dysplasia of the hip in infants is;',
    'Delayed eruption of primary dentition structures',
    'Hyperextension of knees during passive movement testing',
    'Positive Ortolani maneuver during hip joint assessment',
    'Absent Moro reflex during neurological examination procedures',
    'C',
    'Developmental dysplasia of the hip is classically detected by a positive Ortolani (and Barlow) maneuver, where a palpable/audible clunk occurs as the dislocated femoral head reduces into the acetabulum. Other signs include limited abduction and unequal skin folds (Kenya Basic Paediatric Protocols; Nelson Paediatrics).',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Paediatric Nursing',
    'General Paediatric'
) ON CONFLICT (stem, cadre) DO NOTHING;

