) VALUES (
    'A behavior that is most characteristic of toddlers according to normal growth and development patterns is;',
    'Strong desire for autonomy and independence activities',
    'Preference for abstract reasoning and logical analysis',
    'Consistent emotional regulation during stressful situations',
    'Advanced understanding of complex social moral principles',
    'A',
    'Toddlers (Erikson''s autonomy vs shame and doubt stage, 1-3 years) characteristically assert independence, negativism and a strong desire for autonomy. Abstract reasoning, consistent emotional regulation and complex moral understanding develop much later (Kozier; Nelson Paediatrics).',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Paediatric Nursing',
    'General Paediatric'
) ON CONFLICT (stem, cadre) DO NOTHING;

