) VALUES (
    'A child with fever is unable to breastfeed, vomits everything, and has convulsions. Which IMCI classification is most appropriate?',
    'Mild febrile illness',
    'Very severe febrile disease',
    'Malaria with no danger signs',
    'Simple upper respiratory infection',
    'B',
    'In IMCI, a child with fever who has any general danger sign (unable to breastfeed/drink, vomits everything, convulsions, lethargy/unconsciousness) is classified as very severe febrile disease, requiring urgent pre-referral treatment and referral. Danger signs override milder classifications (Kenya IMNCI/IMCI guidelines).',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Paediatric Nursing',
    'General Paediatric'
) ON CONFLICT (stem, cadre) DO NOTHING;

