    'C',
    'Phenobarbital is a barbiturate/CNS depressant; the major dose-related adverse effect to monitor is sedation progressing to respiratory depression. It causes sedation (not hyperactivity), and hypertension/polycythemia are not features (Kenya paediatric protocols; pharmacology).',
    'KRCHN',
