    'Development of trust through caregiver emotional attachment',
    'Establishment of identity and personal role integration',
    'D',
    'In Erikson''s identity vs role confusion stage of adolescence, the central task is establishing a coherent personal identity and integrating roles. Role confusion reflects failure to achieve this identity (Kozier; developmental psychology).',
    'KRCHN',
    'Paper I',
