) VALUES (
    'Digoxin toxicity in a pediatric patient is most likely indicated by:',
    'Bradycardia associated with nausea and vomiting episodes',
    'Tachycardia accompanied by increased physical activity levels',
    'Hypertension occurring during administration of oxygen therapy',
    'Polyuria associated with excessive fluid replacement therapy',
    'A',
    'Digoxin toxicity classically presents with bradycardia and gastrointestinal symptoms such as nausea and vomiting; the nurse must check apical pulse before administration and withhold if the rate is below the age-appropriate threshold. This is standard per Kenyan paediatric pharmacology guidelines and Brunner & Suddarth.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Paediatric Nursing',
    'General Paediatric'
) ON CONFLICT (stem, cadre) DO NOTHING;

