    'Disrupting pregnancy, inhibiting ovulation, inhibiting implantation.',
    'Thickening cervical mucus making it difficult for sperm to penetrate, inhibiting ovulation, thinning the endometrium making it unsuitable for implantation.',
    'Thinning the endometrium making it unsuitable for implantation, disrupting pregnancy, inhibiting ovulation.',
    'Interrupting fertilization and implantation, inhibiting ovulation, thickening cervical mucus making it difficult for sperms to penetrate.',
    'B',
    'Progestin-only implants (Norplant/Jadelle) act by thickening cervical mucus to impede sperm, suppressing ovulation, and thinning the endometrium. They do not disrupt an established pregnancy. Per Kenya National Family Planning Guidelines.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
