) VALUES (
    'The following will result in natural passive immunity:',
    'Administration of immunoglobulins',
    'Administration of modified toxins',
    'Movement of maternal antibodies through the placenta to the foetus',
    'Infection by a disease that confer immunity against itself',
    'C',
    'Natural passive immunity is acquired when preformed maternal antibodies (IgG) cross the placenta to the foetus (and via breast milk). Administration of immunoglobulins is artificial passive immunity, toxoids give artificial active immunity, and infection gives natural active immunity. Thus option C is correct.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Midwifery',
    'General Midwifery'
) ON CONFLICT (stem, cadre) DO NOTHING;

