    difficulty,
    unit,
    topic
) VALUES (
    'The following nursing diagnosis would be most appropriate for a client, who has undergone hysterectomy,',
    'Imbalanced nutrition; less than body requirement related to nausea and vomiting',
    'Excess fluid volume related to surgery',
    'Ineffective breathing pattern related to post-operative pneumonia',
    'Ineffective coping related to body image disturbance',
    'D',
    'Hysterectomy removes the uterus, which many women associate with femininity and reproductive identity, commonly causing altered body image and grief, making ineffective coping related to body image disturbance the most appropriate psychosocial diagnosis. The other options describe complications not specifically characteristic of this procedure. Reference: Brunner & Suddarth; Kozier Fundamentals.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Midwifery',
    'General Midwifery'
) ON CONFLICT (stem, cadre) DO NOTHING;

