    unit,
    topic
) VALUES (
    'When a burn occurs in an adult,',
    'Using rule of nine, right arm is calculated as being 18% & right leg 9%.',
    'Capillaries & small vessels dilate, renal blood flow reduces',
    'Fluid shifts from ICF to ECF space/compartment along with potassium.',
    'Permeability of the kidney tubules increases with oliguria',
    'C',
    'In the emergent/resuscitation phase of a burn, increased capillary permeability causes fluid and potassium to shift out of the intracellular compartment into the extracellular space, producing hyperkalaemia and hypovolaemia (Brunner & Suddarth). The rule-of-nines option is incorrect (arm=9%, leg=18%), and burns cause vasoconstriction/reduced renal flow with oliguria but decreased tubular function, so option C is the accurate physiological statement.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
    'medium',
    'Medical-Surgical Nursing',
    'General Medical-Surgical'
) ON CONFLICT (stem, cadre) DO NOTHING;

