    'Encourage patient to sit in a straight, firm chair for no longer than 20 minutes each time',
    'B',
    'Skeletal traction uses pins/wires through bone, so pin-site care to prevent infection is the appropriate nursing intervention. Cast care and drainage precautions do not apply, and a patient in traction must remain in proper alignment, not sit in a chair (Brunner & Suddarth, orthopaedic nursing).',
    'KRCHN',
