    'Anuria',
    'Polyuria',
    'Dysuria',
    'Dyspnea',
    'A',
    'Anuria (absence of urine output, <100 ml/24h) signals acute kidney failure or complete obstruction and constitutes a medical emergency requiring urgent intervention to prevent fatal uraemia and hyperkalaemia. Polyuria, dysuria and dyspnea are significant but the total cessation of urine production is the true renal emergency here. Reference: Brunner & Suddarth Medical-Surgical Nursing.',
    'KRCHN',
    'Paper I',
