    'C',
    'For an aging patient with urinary incontinence, the priority goal is a reduction in incontinence episodes, which is the direct desired outcome addressing the nursing problem. Recognising urge, mobility and adequate fluids are contributing interventions/means, whereas decreased episodes is the overall priority outcome. Reference: Kozier Fundamentals of Nursing; Brunner & Suddarth.',
    'KRCHN',
    'Paper I',
    2026,
    'approved',
