    status,
    difficulty,
    unit,
    topic
) VALUES (
    'A situation in which the nurse experiences a conflict with personal values or beliefs and some aspect of patient care is',
    'Bioethical conflict',
    'Ethical dilemma',
    'Ethical distress',
    'Ethical conduct',
    'C',
    'Ethical (moral) distress occurs when the nurse''s personal values or beliefs conflict with an aspect of patient care, producing discomfort. Kozier Fundamentals distinguishes this from an ethical dilemma, which is a conflict between two or more competing but equally defensible courses of action requiring a choice. Because the stem describes a values conflict with patient care rather than a choice between two right actions, the answer is ethical distress.',
    'KRCHN',
    'Paper II',
    2022,
    'approved',
    'medium',
    'Mental Health Nursing',
    'General Mental'
) ON CONFLICT (stem, cadre) DO NOTHING;

