) VALUES (
    'Nursing assessment during care plan development differs from medical assessment in that:-',
    'Nursing assessment focuses on patient responses to actual problems',
    'Medical assessment focuses on community health',
    'Medical assessment focuses on health promotion',
    'Nursing assessment diagnoses pathological illness',
    'A',
    'Nursing assessment focuses on the patient''s human responses to actual or potential health problems (nursing diagnoses), whereas medical assessment focuses on diagnosing the disease/pathology. This distinction is core to the nursing process in Kozier Fundamentals.',
    'KRCHN',
    'Paper II',
    2022,
    'approved',
    'medium',
    'Mental Health Nursing',
    'General Mental'
) ON CONFLICT (stem, cadre) DO NOTHING;

