    topic
) VALUES (
    'The pillar of infection control associated with breaking the chain of infection at the reservoir stage is:-',
    'Hand washing',
    'Patient placement',
    'Prudent use of antibiotics',
    'Personal protective equipment',
    'C',
    'The reservoir is where the infectious agent lives and multiplies; breaking the chain at the reservoir includes controlling the source such as prudent/rational antibiotic use to prevent resistant organism reservoirs and treating the source. Hand washing and PPE address the mode of transmission/portals rather than the reservoir per Kenya IPC guidelines.',
    'KRCHN',
    'Paper II',
    2022,
    'approved',
    'medium',
    'Pharmacology',
    'General Pharmacology'
) ON CONFLICT (stem, cadre) DO NOTHING;

