) VALUES (
    'System model theory was formulated by:-',
    'Dorothy Johnson',
    'Virginia Henderson',
    'Imogene King',
    'Jean Watson',
    'A',
    'The Behavioral System Model was developed by Dorothy Johnson, who conceptualised the person as a behavioural system of interrelated subsystems. Imogene King developed the Goal Attainment theory and Jean Watson the theory of Human Caring. Per standard nursing theory texts.',
    'KRCHN',
