    difficulty,
    unit,
    topic
) VALUES (
    'A nurse encounters a situation where a patient is upset and requests a specific medication, but the nurse believes it is not in the patient’s best interest. What is the nurse’s primary responsibility in this situation?',
    'Administering the medication as requested',
    'Discussing the situation with the charge nurse',
    'Explaining the reasons for the decision to the patient',
    'Refusing the patients request without explanation',
    'C',
    'The nurse''s primary responsibility is to uphold beneficence and non-maleficence while respecting patient autonomy through honest communication; this is achieved by explaining the clinical reasons for withholding the requested medication. Administering something not indicated, or refusing without explanation, breaches professional ethics. Per NCK Code of Ethics and Conduct.',
    'KRCHN',
    'Paper II',
    2022,
    'approved',
    'easy',
    'Pharmacology',
    'General Pharmacology'
) ON CONFLICT (stem, cadre) DO NOTHING;

