    unit,
    topic
) VALUES (
    'Foods that may predispose a client to megaloblastic anemia if taken exclusively include:',
    'Meat, eggs and beans',
    'Beans, Peas and rice',
    'Capsicum , Sorghum and Millet',
    'Meat, Maize, Sorghum',
    'B',
    'Megaloblastic anaemia results from folate and/or vitamin B12 deficiency. A diet based exclusively on beans, peas and rice (largely staple/legume, minimal animal-source foods) lacks adequate bioavailable vitamin B12, predisposing to megaloblastic anaemia. Meat, eggs and beans (option A) actually supply B12. Per Kenya nutrition guidelines and Brunner & Suddarth haematology.',
    'KRCHN',
    'Paper II',
    2026,
    'approved',
    'medium',
    'Medical-Surgical Nursing',
    'General Medical-Surgical'
) ON CONFLICT (stem, cadre) DO NOTHING;

