) VALUES (
    'A client tells the nurse that the television newscaster is sending a secret message to her. The nurse suspects the client is experiencing;',
    'A delusion',
    'Flight of ideas',
    'Ideas of reference',
    'A hallucination',
    'C',
    'When a client believes that neutral external events, such as a newscast, carry a special personal message directed at them, this is an idea of reference. It differs from a fixed false belief (delusion) in that it specifically involves misinterpreting external stimuli as personally significant. Kozier/Psychiatric Nursing terminology.',
    'KRCHN',
    'Paper II',
    2026,
    'approved',
    'medium',
    'Mental Health Nursing',
    'General Mental'
) ON CONFLICT (stem, cadre) DO NOTHING;

