    unit,
    topic
) VALUES (
    'A patient has been taking antipsychotic drugs for years. You notice that he begins to grind his teeth, moves and smacks his lips frequently. These features are suggestive of;',
    'Acute dystonia',
    'Gustatory hallucinations',
    'Oculogyric crisis',
    'Tardive dyskinesia',
    'D',
    'Long-term antipsychotic use causes tardive dyskinesia, characterised by involuntary repetitive orofacial movements such as lip smacking, teeth grinding and tongue movements. Acute dystonia and oculogyric crisis are early extrapyramidal effects, not late ones. Kenya Pharmacology/Psychiatric Nursing guidelines.',
    'KRCHN',
    'Paper II',
    2026,
    'approved',
    'medium',
    'Mental Health Nursing',
    'General Mental'
) ON CONFLICT (stem, cadre) DO NOTHING;

