) VALUES (
    'Which nursing action is best when trying to diffuse a client’s impending violent behavior?',
    'Placing the client in seclusion',
    'Leaving the client alone until the client can talk about feelings',
    'Involving the client in a quiet activity to divert attention',
    'Helping the client identify and express feelings of anxiety and anger',
    'D',
    'The least restrictive, most therapeutic de-escalation approach is to help the client identify and verbalise underlying feelings of anxiety and anger before they escalate to violence. Seclusion is a last resort and diversion alone does not address the emotion. Psychiatric Nursing de-escalation principles.',
    'KRCHN',
    'Paper II',
    2026,
    'approved',
    'medium',
    'Mental Health Nursing',
    'General Mental'
) ON CONFLICT (stem, cadre) DO NOTHING;

