    'Fever of unknown origin.',
    'Hip replacement surgery.',
    'D',
    'Critical (clinical) pathways work best for high-volume, predictable conditions with a well-defined, standardised course of care such as elective hip replacement. Conditions of unknown origin or unpredictable course are poorly suited, per nursing management references.',
    'KRCHN',
    'Paper II',
    2026,
    'approved',
    'medium',
    'Medical-Surgical Nursing',
    'General Medical-Surgical'
) ON CONFLICT (stem, cadre) DO NOTHING;

