    unit,
    topic
) VALUES (
    'Q39Nursing intervention that is appropriate for a patient who is suicidal is:',
    'Teach healthier problem-solving skills',
    'Ignore patient’s suicidal comments',
    'Report to the unit doctor',
    'Reassure the patient that suicidal thoughts will be reduced',
    'C',
    'For an actively suicidal patient the priority nursing intervention is ensuring safety, which includes reporting/notifying the treating team so protective measures (constant observation, removal of harmful objects) are instituted. Ignoring comments and false reassurance are both inappropriate, and teaching problem-solving skills is a later therapeutic step once immediate safety is secured (psychiatric/mental health nursing standards). The single most appropriate immediate action among the options is reporting to the unit doctor.',
    'KRCHN',
    'Paper II',
    2026,
    'approved',
    'medium',
    'Mental Health Nursing',
    'General Mental'
) ON CONFLICT (stem, cadre) DO NOTHING;

