) VALUES (
    'Which of the following statements most accurately describes the role of exclusion criteria in clinical trials?',
    'Exclusion criteria help in determining the study''s statistical power by controlling the sample size and adjusting for potential biases in data analysis.',
    'Exclusion criteria are primarily focused on increasing the generalizability of the study findings by including a diverse participant population with varying characteristics.',
    'Exclusion criteria are used to identify participants who meet the inclusion criteria for the study, ensuring that the sample is representative of the target population.',
    'Exclusion criteria are applied to prevent participants with certain characteristics from entering the study to minimize confounding variables and ensure the safety of participants.',
    'D',
    'Exclusion criteria specify characteristics that disqualify potential participants, protecting participant safety and reducing confounding to improve internal validity of the trial, per research methodology. Inclusion criteria (not exclusion) define who qualifies for the study.',
    'KRCHN',
    'Paper II',
    2026,
    'approved',
    'medium',
    'Medical-Surgical Nursing',
