) VALUES (
    'Creation of new words which are not in any vocabulary by a psychiatric patient is called;',
    'Circumstantiality',
    'Neologism',
    'Illusion',
    'Delusion',
    'B',
    'Neologism is the coining of new words that have no meaning in standard vocabulary, a language disturbance seen in psychosis such as schizophrenia, per Kaplan & Sadock. Circumstantiality is over-inclusion of detail, illusion is misperception, and delusion is a false fixed belief.',
    'KRCHN',
