    'An elderly client awaiting hip replacement.',
    'B',
    'Case management targets high-cost, high-acuity, complex clients whose care must be coordinated across the continuum. A trauma victim (gunshot wound) in the ER represents the unpredictable, resource-intensive, multidisciplinary case that most benefits from case management, unlike the routine, predictable outpatient/elective cases. This reflects nursing management principles in NCK leadership curricula (Kozier).',
