    'Shows interest in other patients in the ward.',
    'Completes assigned task',
    'Takes naps during the day',
    'C',
    'In hyperactivity (e.g., mania/ADHD-type presentation), the therapeutic goal is improved attention span, follow-through and the ability to focus and finish activities. Completing an assigned task demonstrates restored concentration and impulse control, the clearest marker of improvement. Reference: NCK mental health nursing curriculum.',
    'KRCHN',
    'Paper II',
    2026,
    'approved',
