    'A',
    'For populations under 10,000, the Fisher''s formula sample size is adjusted (finite population correction) to obtain the final sample size, while for populations of 10,000 or more the unadjusted Fisher''s formula is used. This is the standard convention taught in NCK research methodology.',
    'KRCHN',
