) VALUES (
    'An appropriate description of attention is;',
    'Ability to focus on a particular item.',
    'Ability to sustain one’s focus on an item.',
    'Ability to recall activities in the immediate past.',
    'Ability to concentrate on a particular activity',
    'A',
    'Attention is the ability to focus on a particular stimulus or item, per psychiatric nursing/psychology definitions; sustaining that focus over time is concentration/vigilance. Recall of immediate past events describes memory, so option A best defines attention.',
    'KRCHN',
    'Paper II',
    2026,
    'approved',
    'medium',
    'Mental Health Nursing',
    'General Mental'
) ON CONFLICT (stem, cadre) DO NOTHING;

