    'Observational learning',
    'B',
    'A phobia developing after a dog bite is a learned association between a previously neutral stimulus (dog) and an aversive event (bite), explained by classical (Pavlovian) conditioning, per psychiatric nursing/behavioural theory. Operant conditioning involves reinforcement of behaviour, observational learning is modelling, and cognitive restructuring is a treatment technique.',
    'KRCHN',
    'Paper II',
    2026,
