) VALUES (
    'A researcher investigates whether nurses working night shifts experience higher fatigue levels compared to nurses working day shifts. The researcher does not manipulate any variables but examines existing differences. The study method being used in this case is;',
    'Historical research analyzing records from previous institutions',
    'True experimental research using controlled intervention methods',
    'Causal-comparative research examining possible existing causes',
    'Descriptive research exploring characteristics without comparisons',
    'C',
    'When groups (night vs day shift) that already differ are compared and the researcher does not manipulate any variable, the design is causal-comparative (ex post facto). It examines existing differences to infer possible causes, unlike true experimental research which requires manipulation and control. This is standard nursing research methodology.',
    'KRCHN',
    'Paper II',
    2026,
    'approved',
    'medium',
    'Mental Health Nursing',
    'General Mental'
) ON CONFLICT (stem, cadre) DO NOTHING;

