) VALUES (
    'During systematic desensitization therapy, the nurse should first assist the patient to:',
    'Keep off all situations associated with the feared stimulus',
    'Analyze unconscious conflicts causing irrational fear reactions',
    'Confront the feared object immediately without preparation sessions',
    'Develop relaxation techniques before gradual exposure procedures',
    'D',
    'Systematic desensitization is a behavioral therapy that begins by teaching the patient relaxation techniques, then constructs an anxiety hierarchy and pairs relaxation with gradual, graded exposure to the feared stimulus. Relaxation training is the essential first step. This aligns with standard psychiatric/mental health nursing practice.',
    'KRCHN',
    'Paper II',
    2026,
    'approved',
    'medium',
