) VALUES (
    'A psychiatric patient with aggression will be present with;',
    'Stomping away from the nurses’ station, going to another room, and grabbing a snack from another patient.',
    'Bursting into tears, leaving the community meeting, and sitting on a bed hugging a pillow.',
    'Telling the primary nurse, I felt angry when you said I could not have a second helping at lunch.',
    'Telling the medication nurse, I am not going to take that or any other medication you try to give me.',
    'A',
    'Aggression is behaviour that violates others'' rights/boundaries, here shown by stomping off and taking another patient''s snack. Bursting into tears reflects sadness, and verbally stating anger appropriately or refusing medication assertively are not aggression. This reflects psychiatric nursing assessment of aggressive behaviour.',
    'KRCHN',
    'Paper II',
    2026,
    'approved',
    'medium',
    'Mental Health Nursing',
