    'Null hypothesis denying existence of a relationship',
    'Complex hypothesis involving several independent variables',
    'Directional research hypothesis predicting positive association',
    'Alternative hypothesis suggesting significant variable differences',
    'A',
    'A statement asserting ''there is no relationship'' between variables is the null hypothesis (H0), which denies any association or difference. It is neither directional, complex, nor the alternative hypothesis. This is basic nursing research/statistics knowledge.',
    'KRCHN',
