) VALUES (
    'The type of variables in research that has a potential to influence the outcome of the research and are either unnoticed or uncontrolled are:',
    'Extraneous',
    'Dependent',
    'Independent',
    'Confounding',
    'A',
    'Extraneous variables are those that are unnoticed or uncontrolled yet can influence the study outcome; a confounding variable is a specific extraneous variable that is recognised and related to both the independent and dependent variables. Since the stem stresses ''unnoticed or uncontrolled'', the general category is extraneous variables (Polit & Beck; Kozier research chapter).',
    'KRCHN',
    'Paper II',
    2026,
    'approved',
    'medium',
