) VALUES (
    'A parent has come to the clinic with a 5-year-old boy with history of attacks of frightening with imaginations of snake crawling over him and he is acting as trying to remove it. On assessment the child is cooperative and quite intelligent. The most appropriate explanation for the child behavior is;',
    'Night terror.',
    'Bipolar disorder.',
    'Acute phobic hallucination.',
    'Delusional infestation.',
    'C',
    'A cooperative, intelligent 5-year-old with transient frightening visual experiences (seeing snakes crawling and trying to remove them) reflects acute phobic hallucinations of childhood, a benign self-limiting phenomenon rather than a psychotic or mood disorder. Delusional infestation and bipolar disorder are adult psychiatric conditions, and night terrors occur in sleep with no recall (standard child psychiatry references).',
    'KRCHN',
    'Paper II',
    2026,
    'approved',
    'medium',
    'Paediatric Nursing',
    'General Paediatric'
) ON CONFLICT (stem, cadre) DO NOTHING;

