    unit,
    topic
) VALUES (
    'During a study on medication adherence, several participants relocate and cannot be contacted for follow-up assessments. The limitation likely to occur is;',
    'Attrition affecting completeness of longitudinal data collection',
    'Instrument bias influencing reliability of measurement tools',
    'Recall bias resulting from inaccurate participant memory',
    'Researcher bias caused by subjective data interpretation',
    'A',
    'Loss of participants who relocate and cannot be followed up during a longitudinal adherence study is attrition (loss to follow-up), which reduces sample completeness and threatens internal validity. Per Kozier/nursing research principles, attrition is the specific limitation when participants drop out over repeated follow-up assessments.',
