) VALUES (
    'A student formulates the following: “To prove that poor staffing causes medication errors among nurses.” An appropriate critique for this objective is;',
    'The objective lacks measurable variables for data collection',
    'The objective contains insufficient details about study participants',
    'The objective focuses excessively on descriptive statistical methods',
    'The objective uses a biased action verb suggesting predetermined findings',
    'D',
    'The verb ''to prove'' presupposes the outcome, introducing researcher bias; sound research objectives seek to investigate, examine or determine relationships without a predetermined conclusion (Polit & Beck; standard research methodology). This is the primary methodological flaw.',
    'KRCHN',
