) VALUES (
    'A community health nurse collects data on mothers’ perceptions regarding childhood immunization in a remote village. The data collected are mainly narratives, beliefs, and experiences. The most appropriate type of research would be;',
    'Qualitative research exploring meanings and lived experiences',
    'Quantitative research using numerical statistical comparisons',
    'Correlational research measuring relationships among variables',
    'Experimental research involving random assignment procedures',
    'A',
    'Narratives, beliefs and experiences are non-numerical data best captured by qualitative research, which explores meanings and lived experiences of participants (Polit & Beck; NCK research syllabus). Numerical/correlational/experimental designs do not fit narrative data.',
    'KRCHN',
