) VALUES (
    'A nursing researcher investigating patient satisfaction uses age and educational level as variables that cannot be manipulated. These variables are best classified as:',
    'Extraneous variables threatening internal validity of findings',
    'Active variables created by the investigator during intervention',
    'Demographic or attribute variables beyond researcher control',
    'Continuous variables measured along an infinite numerical scale',
