) VALUES (
    'During a pediatric rotation, a student nurse observes that hospitalized children separated from parents frequently appear anxious and withdrawn. She concludes that separation from parents increases stress among children. Which reasoning process is illustrated?',
    'Deductive reasoning from theory toward specific observations',
    'Experimental reasoning using intervention and comparison groups',
    'Statistical reasoning based on numerical probability analysis',
    'Inductive reasoning from observations toward general conclusions',
    'D',
    'Moving from specific observations (individual anxious children) to a general conclusion (separation increases stress) is inductive reasoning (Polit & Beck). Deductive reasoning moves from general theory to specific cases, the reverse direction.',
    'KRCHN',
    'Paper II',
    2026,
    'approved',
    'medium',
    'Paediatric Nursing',
