    'An exam that measures the intended construct (infection prevention knowledge) and not an irrelevant construct (mathematics) demonstrates construct validity, the degree to which a tool measures the theoretical concept it claims to measure. Face validity is only about surface appearance; external and predictive validity concern generalization and future outcomes.',
    'KRCHN',
    'Paper II',
    2026,
    'approved',
    'medium',
    'Community Health Nursing',
    'General Community'
) ON CONFLICT (stem, cadre) DO NOTHING;

