    'Basic training of teachers, health education, immunization and counseling.',
    'A',
    'The school health nurse''s core functions include physical/health assessment of pupils (and staff), health education, and maintaining public relations/liaison with the school and community. Kenya School Health Policy and community health nursing texts list these as legitimate SHN roles. The other options mix in tasks like ''basic training of teachers'' that are not core SHN functions, making option A the most accurate composite.',
