    'Satisfying hunger, preventing prolapse of rectum, regulating meatabolic rate.',
    'Regulating the functions of muscles and nerves, aiding in defaecation, regulating metabolic rate.',
    'A',
    'Dietary fibre (roughage) adds bulk, stimulates peristalsis to move food along the gut, aids elimination of waste, and prevents constipation. Kozier Fundamentals and nutrition texts describe exactly these functions. Fibre itself does not provide vitamins or regulate body temperature, eliminating the other options.',
    'KRCHN',
    'Paper II',
    2026,
    'approved',
    'medium',
    'Mental Health Nursing',
    'General Mental'
) ON CONFLICT (stem, cadre) DO NOTHING;

INSERT INTO questions (
    stem,
    option_a,
