    cadre,
    paper,
    exam_year,
    status,
    difficulty,
    unit,
    topic
) VALUES (
    'Some of the requirements for a good rural house are:-',
    'Adequate water supply, made of a hard floor and walls, has a pit latrine.',
    'Should be built on dry ground, separate accommodation for humans and animals has a good pit latrine.',
    'Separate provisions for food storage and prevention, adequate light and ventilation, piped water supply.',
    'Adequate means of refuse disposal, built away from flooding, separate bedroom for each family member.',
    'B',
    'Environmental health standards for a good rural house require siting on dry, well-drained ground, separation of human and animal housing, and safe excreta disposal (a good pit latrine). Piped water is not realistic as a rural-house requirement, and ''separate bedroom for each family member'' is not a standard rural requirement, so option B is the best composite per Kenya environmental health guidance.',
    'KRCHN',
    'Paper II',
    2026,
    'approved',
    'medium',
    'Community Health Nursing',
    'General Community'
) ON CONFLICT (stem, cadre) DO NOTHING;

