) VALUES (
    'The performance of an immunization programme can be evaluated through:-',
    'Supervisory visits, special surveys, BCG scars.',
    'Routine reporting, mass campaigns, special surveys.',
    'Routine supervisory visits, special surveys, routine reporting.',
    'Cold chain maintenance, special surveys, supervisory visits.',
    'C',
    'Immunization programme performance is evaluated through routine reporting (coverage/administrative data), routine supervisory visits, and special surveys (e.g., coverage surveys). Mass campaigns and cold chain maintenance are activities/inputs, not evaluation methods, so option C best captures the standard EPI monitoring and evaluation methods.',
    'KRCHN',
    'Paper II',
    2026,
    'approved',
    'hard',
    'Medical-Surgical Nursing',
    'General Medical-Surgical'
) ON CONFLICT (stem, cadre) DO NOTHING;

