) VALUES (
    'The measures taken to prevent dental carries include:-',
    'Limiting sugary foods, regular dental check-up, maintenance of good oral hygiene.',
    'Regular brushing of teeth, limiting sugary foods, avoiding smoking.',
    'Balanced diet, physical exercises, proper oral hygiene.',
    'Exercising the teeth by chewing regularly, dental check up, high carbohydrate diet.',
    'A',
    'Prevention of dental caries centres on reducing dietary sugars, regular dental check-ups for early detection, and good oral hygiene (brushing, and where available fluoride). Option A lists these evidence-based measures, whereas other options include irrelevant or harmful items such as ''high carbohydrate diet''.',
    'KRCHN',
    'Paper II',
    2026,
    'approved',
    'medium',
