    exam_year,
    status,
    difficulty,
    unit,
    topic
) VALUES (
    'A six year old child presents at the child clinic with oedema and his weight is 60% below normal. This child is likely to be suffering from:',
    'Underweight',
    'Kwashiorkor',
    'Marasmus',
    'Marasmic kwashiorkor',
    'B',
    'Bilateral pitting oedema is the defining clinical hallmark of kwashiorkor (oedematous protein-energy malnutrition), and Kenya IMNCI/nutrition protocols classify oedema of both feet as oedematous severe acute malnutrition. Marasmus is severe wasting WITHOUT oedema, so the presence of oedema points to kwashiorkor. Marasmic kwashiorkor requires clearly documented severe visible wasting together with oedema; the stem emphasises oedema as the presenting feature, making kwashiorkor the intended single best answer.',
    'KRCHN',
    'Paper II',
    2026,
    'approved',
    'medium',
    'Paediatric Nursing',
    'General Paediatric'
) ON CONFLICT (stem, cadre) DO NOTHING;

