) VALUES (
    'A disease with a constant high prevalence in a population is referred to as:',
    'Epidemic',
    'Hyperendemic',
    'Endemic',
    'Pandemic',
    'C',
    'A disease with a constant, habitual presence at a relatively stable prevalence within a given population/geographic area is termed endemic. Hyperendemic implies persistently high and equal transmission, while epidemic and pandemic denote excess/spreading occurrence. Per Kenya community health and standard epidemiology texts.',
    'KRCHN',
    'Paper II',
    2026,
    'approved',
    'medium',
    'Community Health Nursing',
    'General Community'
) ON CONFLICT (stem, cadre) DO NOTHING;

