    'C',
    'A rare but recognised complication of IUCD use is uterine perforation with migration of the device into the abdominal cavity or adjacent organs. IUCDs can be inserted at any time in the cycle if pregnancy is excluded and immediately postpartum, and are actually suitable for women with ischaemic heart disease as they are non-hormonal; thus migration is the correct true statement.',
    'KRCHN',
