    exam_year,
    status,
    difficulty,
    unit,
    topic
) VALUES (
    'The best method of preventing water washed diseases is;',
    'Improve the quality of water',
    'Minimize the  contact between people and water',
    'Protect water sources from contamination',
    'Improve the quantity of water.',
    'D',
    'Water-washed (water-scarce) diseases such as scabies, trachoma, and skin/eye infections result from insufficient water for personal hygiene, so the key preventive measure is increasing the QUANTITY of water available for washing and hygiene (Kenya Environmental Health/PHC principles). Improving water quality prevents water-borne diseases, not water-washed diseases. The correct answer is to improve the quantity of water.',
    'KRCHN',
    'Paper II',
    2026,
    'approved',
    'medium',
    'Community Health Nursing',
    'General Community'
) ON CONFLICT (stem, cadre) DO NOTHING;

