    exam_year,
    status,
    difficulty,
    unit,
    topic
) VALUES (
    'The immediate care of a patient confirmed to have cholera at the health centre is;',
    'Administer intravenous fluid, refer the patient to hospital',
    'Administer tetracycline, refer the patient to hospital',
    'Administer intravenous fluid, administer antibiotic',
    'Take stool for culture, administer tetracycline',
    'A',
    'The immediate life-saving priority in confirmed cholera at a health centre is aggressive rehydration with IV fluids (Ringer''s lactate) to correct hypovolaemia, followed by referral for continued management (Kenya MOH cholera guidelines). Antibiotics (doxycycline) are an adjunct that shortens illness and reduces shedding but are not the immediate life-saving intervention. Therefore administer IV fluid and refer is the correct immediate care.',
    'KRCHN',
    'Paper II',
    2026,
    'approved',
    'medium',
    'Pharmacology',
    'General Pharmacology'
) ON CONFLICT (stem, cadre) DO NOTHING;

