    'A',
    'Rabies classically presents with a history of animal (dog) bite, hydrophobia with difficulty swallowing, and excessive salivation/drooling due to pharyngeal spasm. Option A captures the pathognomonic triad. Per Kenya MOH communicable disease guidelines these are the hallmark features of clinical rabies.',
    'KRCHN',
    'Paper II',
    2026,
    'approved',
    'medium',
    'Medical-Surgical Nursing',
    'General Medical-Surgical'
) ON CONFLICT (stem, cadre) DO NOTHING;

