    'Results from low infection pressure.',
    'It is applicable in all immunizable diseases.',
    'Occurs when the percentage of immunized people is high',
    'It is achieved by keeping the susceptible cases low',
    'B',
    'Herd (herd/''hard'') immunity does NOT apply to all immunizable diseases; it only works for diseases spread person-to-person, not for those with non-human reservoirs (e.g., tetanus, where herd immunity does not protect). It results from high immunization coverage, low infection pressure and keeping susceptibles low. Thus the false statement is B. Per epidemiology/PHC principles.',
    'KRCHN',
    'Paper II',
    2026,
    'approved',
    'medium',
